-- Steg-för-steg-instruktioner (sv+en) för nya biblioteket, från det
-- licensierade ExerciseDB-paketet med svenska översättningar. Lagras i
-- databasen istället för appbundlen. Idempotent.

ALTER TABLE exercises ADD COLUMN IF NOT EXISTS instructions jsonb;

UPDATE exercises SET instructions = $instr$[{"sv": "Ligg platt på rygg med knäna böjda och fötterna i golvet.", "en": "Lie flat on your back with your knees bent and feet flat on the ground."}, {"sv": "Placera händerna bakom huvudet med armbågarna pekande utåt.", "en": "Place your hands behind your head with your elbows pointing outwards."}, {"sv": "Spänn magen och lyft långsamt överkroppen från golvet, rulla framåt tills överkroppen är i 45 graders vinkel.", "en": "Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle."}, {"sv": "Pausa ett ögonblick i toppläget och sänk sedan långsamt tillbaka överkroppen till startpositionen.", "en": "Pause for a moment at the top, then slowly lower your upper body back down to the starting position."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = '3/4 sit-up' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Börja med att stå med fötterna axelbrett isär och håll EZ-stången med överhandsgrepp.", "en": "Start by standing with your feet shoulder-width apart and holding the ez barbell with an overhand grip."}, {"sv": "Lyft stången till axelhöjd med armbågarna lätt böjda och handflatorna vända framåt.", "en": "Raise the barbell to shoulder height, keeping your elbows slightly bent and your palms facing forward."}, {"sv": "Pressa stången över huvudet och sträck ut armarna helt.", "en": "Press the barbell overhead, extending your arms fully."}, {"sv": "Sänk tillbaka stången till axelhöjd och upprepa önskat antal repetitioner.", "en": "Lower the barbell back to shoulder height and repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Anti gravity press med EZ-stång' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Börja i armhävningsposition med händerna något bredare än axelbrett.", "en": "Start in a push-up position with your hands slightly wider than shoulder-width apart."}, {"sv": "Sträck ut ena armen rakt åt sidan, parallellt med golvet.", "en": "Extend one arm straight out to the side, parallel to the ground."}, {"sv": "Sänk kroppen genom att böja armbågarna, håll ryggen rak och bålen spänd.", "en": "Lower your body by bending your elbows, keeping your back straight and core engaged."}, {"sv": "Pressa dig tillbaka upp till startpositionen.", "en": "Push back up to the starting position."}, {"sv": "Upprepa på andra sidan och sträck ut motsatt arm åt sidan.", "en": "Repeat on the other side, extending the opposite arm out to the side."}, {"sv": "Fortsätt växla sida i önskat antal repetitioner.", "en": "Continue alternating sides for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Archer armhävning' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Börja med att hänga i en pull-up-stång med överhandsgrepp, något bredare än axelbrett.", "en": "Start by hanging from a pull-up bar with an overhand grip, slightly wider than shoulder-width apart."}, {"sv": "Spänn bålen och dra skulderbladen nedåt och bakåt.", "en": "Engage your core and pull your shoulder blades down and back."}, {"sv": "När du drar dig upp, böj ena armen och för armbågen mot sidan medan du håller den andra armen rak.", "en": "As you pull yourself up, bend one arm and bring your elbow towards your side, while keeping the other arm straight."}, {"sv": "Fortsätt dra tills hakan är ovanför stången och den böjda armen är helt böjd.", "en": "Continue pulling until your chin is above the bar and your bent arm is fully flexed."}, {"sv": "Sänk dig tillbaka ned med kontroll, sträck ut den böjda armen och upprepa rörelsen på andra sidan.", "en": "Lower yourself back down with control, straightening the bent arm and repeating the movement on the other side."}, {"sv": "Växla sida för varje repetition.", "en": "Alternate sides with each repetition."}]$instr$::jsonb WHERE name = 'Archer pull-up' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Börja med att ligga plant på rygg med böjda knän och fötterna plant i golvet.", "en": "Start by lying flat on your back with your knees bent and feet flat on the ground."}, {"sv": "Placera händerna bakom huvudet med armbågarna pekande utåt.", "en": "Place your hands behind your head with your elbows pointing outwards."}, {"sv": "Spänn magen och lyft överkroppen från golvet, och för höger armbåge mot vänster knä.", "en": "Engage your abs and lift your upper body off the ground, bringing your right elbow towards your left knee."}, {"sv": "För samtidigt vänster knä mot höger armbåge så att det blir en vridande rörelse.", "en": "At the same time, bring your left knee towards your right elbow, creating a twisting motion."}, {"sv": "Pausa ett ögonblick i toppen, sänk sedan långsamt överkroppen och sträck ut benen tillbaka till startpositionen.", "en": "Pause for a moment at the top, then slowly lower your upper body and extend your legs back to the starting position."}, {"sv": "Upprepa rörelsen, denna gång med vänster armbåge mot höger knä och höger knä mot vänster armbåge.", "en": "Repeat the movement, this time bringing your left elbow towards your right knee and your right knee towards your left elbow."}, {"sv": "Fortsätt växla sida i önskat antal repetitioner.", "en": "Continue alternating sides for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Armbåge mot knä' AND user_id IS NULL;
