UPDATE exercises SET instructions = $instr$[{"sv": "Börja i armhävningsposition med händerna något bredare än axelbrett och fötterna ihop.", "en": "Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together."}, {"sv": "Sträck ena armen rakt ut åt sidan, parallellt med golvet.", "en": "Extend one arm straight out to the side, parallel to the ground."}, {"sv": "Sänk kroppen mot golvet genom att böja armbågen, håll ryggen rak och bålen spänd.", "en": "Lower your body towards the ground by bending your elbows, keeping your back straight and core engaged."}, {"sv": "Pressa tillbaka upp till startpositionen och använd bröstmusklerna för att lyfta kroppen.", "en": "Push back up to the starting position, using your chest muscles to lift your body."}, {"sv": "Upprepa med andra armen utsträckt.", "en": "Repeat with the other arm extended."}]$instr$::jsonb WHERE name = 'Armhävning med enarmslyft' AND user_id IS NULL;
