UPDATE exercises SET instructions = $instr$[{"sv": "Börja i hög planka med händerna något bredare än axelbrett och kroppen i en rak linje från huvud till hälar.", "en": "Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line from head to heels."}, {"sv": "Sänk kroppen mot golvet genom att böja armbågarna, håll dem nära sidorna.", "en": "Lower your body towards the ground by bending your elbows, keeping them close to your sides."}, {"sv": "När du pressar upp igen, lyft höger hand från golvet och nudda vänster axel.", "en": "As you push back up, lift your right hand off the ground and tap your left shoulder."}, {"sv": "Sätt tillbaka höger hand i golvet och upprepa armhävningen, denna gång lyfter du vänster hand och nuddar höger axel.", "en": "Return your right hand to the ground and repeat the push-up, this time lifting your left hand and tapping your right shoulder."}, {"sv": "Fortsätt växla axel vid varje armhävning.", "en": "Continue alternating shoulder taps with each push-up repetition."}, {"sv": "Håll bålen stabil och undvik överdriven höftrotation genom hela övningen.", "en": "Maintain a stable core and avoid excessive hip rotation throughout the exercise."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Armhävning med shoulder tap' AND user_id IS NULL;
