UPDATE exercises SET instructions = $instr$[{"sv": "Börja med att placera händerna på en upphöjd yta, till exempel en bänk eller parallella stänger, med handflatorna nedåt och fingrarna pekande framåt.", "en": "Start by placing your hands on a raised surface, such as a bench or parallel bars, with your palms facing down and fingers pointing forward."}, {"sv": "Sträck benen framför dig, med hälarna i golvet och kroppen rak.", "en": "Extend your legs out in front of you, keeping your heels on the ground and your body straight."}, {"sv": "Sänk kroppen genom att böja armbågarna nära kroppens sidor, tills överarmarna är parallella med golvet.", "en": "Lower your body by bending your elbows, keeping them close to your sides, until your upper arms are parallel to the ground."}, {"sv": "Pausa ett ögonblick och pressa sedan genom handflatorna för att sträcka armarna och lyfta kroppen tillbaka till startpositionen.", "en": "Pause for a moment, then push through your palms to straighten your arms and lift your body back up to the starting position."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Body-up' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Stå med fötterna axelbrett isär och håll en kettlebell i ena handen med överhandsgrepp.", "en": "Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip."}, {"sv": "Böj knäna lätt och fäll fram i höften, med rak rygg och bröstet upp.", "en": "Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up."}, {"sv": "Låt kettlebellen hänga ner mellan benen med armen helt sträckt.", "en": "Allow the kettlebell to hang down between your legs, with your arm fully extended."}, {"sv": "Sträck explosivt i höfter och knän och dra samtidigt kettlebellen upp mot axeln i en enda flytande rörelse.", "en": "In one fluid motion, explosively extend your hips and knees while pulling the kettlebell up towards your shoulder."}, {"sv": "När kettlebellen når axelhöjd, rotera handleden så att kettlebellens botten pekar uppåt.", "en": "As the kettlebell reaches shoulder height, rotate your wrist so that the bottom of the kettlebell is facing up."}, {"sv": "Fånga kettlebellen i axelhöjd med böjd armbåge och handflatan uppåt.", "en": "Catch the kettlebell at shoulder height with your elbow bent and your palm facing up."}, {"sv": "Sänk kettlebellen tillbaka till startpositionen genom att vända på rörelsen.", "en": "Lower the kettlebell back down to the starting position by reversing the movement."}, {"sv": "Upprepa önskat antal repetitioner och byt sedan sida.", "en": "Repeat for the desired number of repetitions, then switch sides."}]$instr$::jsonb WHERE name = 'Bottoms up hang clean med kettlebell' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Ligg platt på rygg med benen sträckta och armarna längs sidorna.", "en": "Lie flat on your back with your legs extended and your arms by your sides."}, {"sv": "Böj knäna och för dem mot bröstet, med fötterna ovanför golvet.", "en": "Bend your knees and bring them towards your chest, keeping your feet off the ground."}, {"sv": "Spänn magen och lyft höfterna från golvet, och för knäna mot huvudet.", "en": "Engaging your abs, lift your hips off the ground, bringing your knees towards your head."}, {"sv": "Pausa ett ögonblick i toppen och sänk sedan långsamt höfterna tillbaka till startpositionen.", "en": "Pause for a moment at the top, then slowly lower your hips back down to the starting position."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Bottoms-up' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Inta boxningsställning med vänster fot fram (ortodox), mjuka knän, indragen haka, händerna i kindhöjd och armbågarna intill kroppen.", "en": "Adopt a boxing stance with the left foot forward (orthodox), knees soft, chin tucked, hands at cheek level and elbows in."}, {"sv": "Sjunk ner lätt genom att böja knäna och ladda främre (vänster) höft utan att sjunka ihop i överkroppen.", "en": "Dip slightly by bending the knees and loading the lead (left) hip without collapsing your torso."}, {"sv": "Tryck ifrån golvet med vänster fot, rotera höfter och överkropp, och låt vänster axel lyftas när du inleder slaget.", "en": "Drive through the floor with the left foot, rotate the hips and torso, and let the left shoulder rise as you start the punch."}, {"sv": "Håll vänster armbåge nära kroppen och skicka knytnäven uppåt framför överkroppen, med handflatan mot dig eller lätt inåt. Sväng inte ut brett.", "en": "Keep the left elbow close to your body and send the fist up in front of your torso, palm facing you or slightly inward; do not scoop wide."}, {"sv": "Andas ut kraftigt vid träffen, med rak handled och underarmen lodrätt under knogarna.", "en": "Exhale sharply at impact, keeping the wrist straight and forearm vertical under the knuckles."}, {"sv": "Stoppa slaget strax framför kroppslinjen, dra sedan tillbaka längs samma bana och återgå till gard.", "en": "Stop the punch just in front of your body line, then retract along the same path and return to guard."}, {"sv": "Återställ din ställning utan att överrotera eller luta dig framåt, och upprepa sedan i reps eller på tid.", "en": "Reset your stance without over-rotating or leaning forward, then repeat for reps or time."}]$instr$::jsonb WHERE name = 'Boxning vänster uppercut' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Stå i boxningsställning med främre foten fram, mjuka knän, indragen haka och händerna uppe i kindhöjd.", "en": "Stand in a boxing stance with lead foot forward, knees soft, chin tucked, hands up at cheek level."}, {"sv": "Spänn bålen och håll bakre handen tätt mot ansiktet hela tiden.", "en": "Brace your core and keep the rear hand tight to your face throughout."}, {"sv": "Inled jabben genom att trycka lätt ifrån med bakre foten samtidigt som du roterar främre höften och axeln mot målet.", "en": "Initiate the jab by lightly pushing from the rear foot as you rotate the lead hip and shoulder toward the target."}, {"sv": "Sträck främre armen rakt fram och rotera knytnäven till handflatan nedåt nära full sträckning. Håll handleden neutral och undvik att låsa armbågen.", "en": "Extend the lead arm straight ahead, rotating the fist to palm-down near full extension; keep the wrist neutral and avoid locking the elbow."}, {"sv": "Låt axeln skjutas framåt för räckvidd utan att dra upp den mot örat. Andas ut kraftigt i slaget.", "en": "Let the shoulder protract for reach without shrugging; exhale sharply on the punch."}, {"sv": "Dra snabbt tillbaka handen rakt längs samma bana till gard, samtidigt som höfter och axlar centreras igen.", "en": "Snap the hand straight back along the same path to your guard as the hips and shoulders re-center."}, {"sv": "Håll balansen och upprepa med mjuka, snabba reps medan bakre handen hålls uppe.", "en": "Maintain balance and repeat with smooth, quick reps while keeping the rear hand up."}]$instr$::jsonb WHERE name = 'Boxningsjabb' AND user_id IS NULL;
