UPDATE exercises SET instructions = $instr$[{"sv": "Stå upprätt på ett ben vänd mot plankan eller målet, med bålen spänd och höft, knä och tå i linje.", "en": "Stand tall on one leg facing the board/target, core braced, hip–knee–toe aligned."}, {"sv": "Fäll lätt i höften och sjunk ner i en kvartsböj, svep armarna bakåt och håll det fria benet bakom dig för balans.", "en": "Hinge slightly and descend into a quarter squat, arms sweeping back, free leg behind for balance."}, {"sv": "Tryck ifrån genom ståfoten och sträck fotled, knä och höft för att hoppa framåt.", "en": "Drive through the standing foot, extending ankle, knee, and hip to jump forward."}, {"sv": "Svinga armarna framåt som hjälp, håll överkroppen kontrollerad och knät i linje över tårna.", "en": "Swing the arms forward to assist, keeping the torso controlled and knee tracking over toes."}, {"sv": "Landa mjukt på samma fot, från trampdynan till hälen, med böjt knä och höfterna bakåt.", "en": "Land softly on the same foot, ball-to-heel, with knee bent and hips back."}, {"sv": "Håll och stabilisera i 1-2 sekunder utan att knät faller inåt.", "en": "Hold and stabilize for 1–2 seconds without the knee collapsing inward."}, {"sv": "Återställ hållningen och upprepa önskat antal repetitioner, byt sedan ben.", "en": "Reset posture and repeat for reps, then switch legs."}]$instr$::jsonb WHERE name = 'Enbens längdhopp' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Stå med fötterna höftbrett isär och håll en hantel i höger hand.", "en": "Stand with your feet hip-width apart, holding a dumbbell in your right hand."}, {"sv": "Flytta vikten till vänster ben och lyft höger fot en aning från golvet.", "en": "Shift your weight onto your left leg and lift your right foot slightly off the ground."}, {"sv": "Håll ryggen rak, fäll fram från höften och sänk hanteln mot golvet.", "en": "Keeping your back straight, hinge forward at the hips and lower the dumbbell towards the ground."}, {"sv": "Sträck samtidigt höger ben rakt bakåt och behåll en lätt böj i vänster knä.", "en": "At the same time, extend your right leg straight behind you, maintaining a slight bend in your left knee."}, {"sv": "Sänk hanteln tills överkroppen och höger ben är parallella med golvet.", "en": "Lower the dumbbell until your torso and right leg are parallel to the ground."}, {"sv": "Pausa ett ögonblick, spänn sedan sätesmuskler och baksida lår för att återgå till startpositionen.", "en": "Pause for a moment, then engage your glutes and hamstrings to return to the starting position."}, {"sv": "Upprepa önskat antal repetitioner och byt sedan sida.", "en": "Repeat for the desired number of repetitions, then switch sides."}]$instr$::jsonb WHERE name = 'Enbens marklyft med hantel' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Placera en låg stepbräda eller låda 30 till 45 cm bakom dig och låt tårna på den fot som inte arbetar vila lätt mot den. Stå upprätt på det arbetande benet och håll en hantel med rak arm i handen på samma sida.", "en": "Place a low step/box 30–45 cm behind you and lightly rest the toes of the non-working foot on it; stand tall on the working leg holding a dumbbell in the same-side hand, arm straight."}, {"sv": "Placera den arbetande foten under höften, håll knät mjukt (10 till 20 graders böj), spänn bålen och håll höfter och axlar riktade rakt fram.", "en": "Set the working foot under the hip, keep a soft knee (10–20° bend), brace your core, and keep hips and shoulders square."}, {"sv": "Fäll i höften genom att pressa den bakåt, håll hanteln nära smalbenet och vinkeln i det arbetande knät nästan oförändrad.", "en": "Hinge at the hips by pushing them back, keeping the dumbbell close to your shin and the working knee angle nearly constant."}, {"sv": "Behåll neutral rygg från huvud till bäcken. Sänk tills du känner en tydlig sträckning i baksida lår eller tills överkroppen närmar sig parallell med golvet, utan att runda ryggen.", "en": "Maintain a neutral spine from head to pelvis; lower until you feel a firm hamstring stretch or your torso nears parallel without rounding."}, {"sv": "Håll 80 till 90 procent av vikten på det arbetande benet. Den bakre foten är bara till för balans, inte för att trycka ifrån med.", "en": "Keep 80–90% of your weight on the working leg; the rear foot is for balance only, not to push from."}, {"sv": "Tryck ifrån genom den arbetande hälen, sträck höften och res dig upp utan att översträcka ländryggen.", "en": "Drive through the working heel, extend the hip, and return to stand without hyperextending the lower back."}, {"sv": "Återställ bålspänningen och upprepa önskat antal reps, byt sedan sida.", "en": "Reset your brace and repeat for reps, then switch sides."}]$instr$::jsonb WHERE name = 'Enbens marklyft med hantel och stöd på stepbräda' AND user_id IS NULL;
