UPDATE exercises SET instructions = $instr$[{"sv": "Stå med fötterna axelbrett isär och håll en hantel i varje hand.", "en": "Stand with your feet shoulder-width apart, holding a dumbbell in each hand."}, {"sv": "Ta ett steg framåt med ena foten och placera fötterna så att den främre foten står platt i golvet och den bakre foten vilar upphöjd på en bänk eller stepbräda.", "en": "Take a step forward with one foot and position your feet so that your front foot is flat on the ground and your back foot is elevated on a bench or step."}, {"sv": "Sänk kroppen genom att böja främre knät och höften, håll det bakre knät lätt böjt och den bakre hälen lyft från golvet.", "en": "Lower your body by bending your front knee and hip, keeping your back knee slightly bent and your back heel off the ground."}, {"sv": "Fortsätt sänka tills det främre låret är parallellt med golvet och tryck sedan ifrån genom främre hälen för att återgå till startpositionen.", "en": "Continue lowering until your front thigh is parallel to the ground, then push through your front heel to return to the starting position."}, {"sv": "Upprepa önskat antal repetitioner, byt sedan ben och upprepa.", "en": "Repeat for the desired number of repetitions, then switch legs and repeat."}]$instr$::jsonb WHERE name = 'Enbens split squat med hantlar' AND user_id IS NULL;
