UPDATE exercises SET instructions = $instr$[{"sv": "Stå upprätt på ett ben med det andra knät lätt böjt och armarna längs sidorna.", "en": "Stand tall on one leg with the other knee slightly flexed and arms by your sides."}, {"sv": "Spänn bålen, håll bröstet uppe och rikta ståbenets knä över tårna.", "en": "Engage your core, keep your chest up, and align the stance knee over the toes."}, {"sv": "Fäll lätt i höfterna och sjunk ner i en kvartsböj för att ladda benet.", "en": "Hinge slightly at the hips and dip into a quarter squat to load the leg."}, {"sv": "Svinga armarna uppåt och tryck ifrån genom hela foten, sträck höft, knä och fotled för att hoppa rakt upp.", "en": "Swing the arms upward and drive through the whole foot, extending hip, knee, and ankle to jump vertically."}, {"sv": "Lyft det andra benets knä uppåt när du når maximal höjd och håll överkroppen neutral.", "en": "Lift the non-jumping knee up as you reach maximal height while keeping the torso neutral."}, {"sv": "Landa tyst på samma ben med mjukt knä och mjuk höft, ta upp stöten genom höft, knä och fotled.", "en": "Land quietly on the same leg with a soft knee and hip, absorbing the impact through hip–knee–ankle."}, {"sv": "Återfå balansen och upprepa önskat antal repetitioner, byt sedan ben. Håll knät i linje över tårna och undvik att det faller inåt.", "en": "Reset balance and repeat for reps, then switch legs. Keep the knee tracking over the toes and avoid valgus collapse."}]$instr$::jsonb WHERE name = 'Enbens vertikalhopp' AND user_id IS NULL;
