UPDATE exercises SET instructions = $instr$[{"sv": "Stå med fötterna axelbrett isär och håll en skivstång med överhandsgrepp, med händerna bredare än axelbrett.", "en": "Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands wider than shoulder-width apart."}, {"sv": "Låt skivstången hänga framför låren med helt sträckta armar.", "en": "Let the barbell hang in front of your thighs, arms fully extended."}, {"sv": "Håll ryggen rak, andas ut och dra skivstången rakt upp mot hakan med armbågarna först.", "en": "Keeping your back straight, exhale and lift the barbell straight up towards your chin, leading with your elbows."}, {"sv": "Pausa ett ögonblick i toppen, andas sedan in och sänk långsamt skivstången tillbaka till startpositionen.", "en": "Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Hakdrag brett grepp' AND user_id IS NULL;
