UPDATE exercises SET instructions = $instr$[{"sv": "Sitt eller stå upprätt med avslappnade axlar och blicken rakt fram.", "en": "Sit or stand upright with shoulders relaxed and eyes looking straight ahead."}, {"sv": "Spänn bålen lätt och håll käken avslappnad.", "en": "Brace lightly through your midsection and keep your jaw relaxed."}, {"sv": "Utan att tippa huvudet uppåt eller nedåt, dra hakan rakt bakåt som om huvudet gled längs en räls.", "en": "Without tilting your head up or down, draw your chin straight backward as if sliding your head along a track."}, {"sv": "Känn hur nackens baksida förlängs och halsens framsida aktiveras lätt, håll blicken i samma höjd.", "en": "Feel the back of your neck lengthen and the front of your neck gently engage; keep eyes level."}, {"sv": "Håll i 3 till 5 sekunder medan du andas normalt.", "en": "Hold for 3–5 seconds while breathing normally."}, {"sv": "Återgå långsamt till startpositionen och upprepa i 8 till 12 kontrollerade reps.", "en": "Slowly return to the starting position and repeat for 8–12 controlled reps."}]$instr$::jsonb WHERE name = 'Hakindragning' AND user_id IS NULL;
