UPDATE exercises SET instructions = $instr$[{"sv": "Hitta en vägg, vänd ryggen mot den och ställ dig en knapp meter ifrån.", "en": "Find a wall and face away from it, standing a few feet away."}, {"sv": "Placera händerna i golvet axelbrett isär och sparka upp fötterna mot väggen så att du kommer upp i handstående.", "en": "Place your hands on the ground shoulder-width apart and kick your feet up against the wall, coming into a handstand position."}, {"sv": "Böj armbågarna och sänk huvudet mot golvet med kroppen i en rak linje.", "en": "Bend your elbows and lower your head towards the ground, keeping your body in a straight line."}, {"sv": "Tryck genom händerna och sträck ut armarna för att återgå till startpositionen.", "en": "Push through your hands and extend your arms to return to the starting position."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Handstående armhävning' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Stå med fötterna axelbrett isär och håll en kettlebell framför låren.", "en": "Stand with your feet shoulder-width apart, holding a kettlebell in front of your thighs."}, {"sv": "Böj knäna lätt och fäll fram i höften med rak rygg.", "en": "Bend your knees slightly and hinge forward at the hips, keeping your back straight."}, {"sv": "Sänk kettlebellen mot golvet och låt den svinga mellan benen.", "en": "Lower the kettlebell towards the ground, allowing it to swing between your legs."}, {"sv": "Sträck snabbt i höfter och knän och använd farten för att svinga kettlebellen upp till axelhöjd.", "en": "Quickly extend your hips and knees, using the momentum to swing the kettlebell up to shoulder height."}, {"sv": "När kettlebellen når axelhöjd, rotera handlederna och fånga kettlebellen i rackposition, med armbågen intill kroppen och kettlebellen vilande mot underarmen.", "en": "As the kettlebell reaches shoulder height, rotate your wrists and catch the kettlebell in the rack position, with your elbow tucked in and the kettlebell resting on your forearm."}, {"sv": "Sänk kettlebellen tillbaka till startpositionen mellan benen och upprepa önskat antal repetitioner.", "en": "Lower the kettlebell back down to the starting position between your legs, and repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Hang clean med kettlebell' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Stå med fötterna axelbrett isär och håll en hantel i varje hand, handflatorna framåt.", "en": "Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward."}, {"sv": "Sträck ut ena benet bakom dig och balansera på den fotens tår.", "en": "Extend one leg behind you, balancing on the toes of that foot."}, {"sv": "Håll överarmarna stilla, andas ut och curla vikterna samtidigt som du spänner biceps.", "en": "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps."}, {"sv": "Fortsätt lyfta vikterna tills biceps är helt kontraherade och hantlarna är i axelhöjd.", "en": "Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level."}, {"sv": "Håll den kontraherade positionen en kort paus medan du kniper åt i biceps.", "en": "Hold the contracted position for a brief pause as you squeeze your biceps."}, {"sv": "Andas in och börja långsamt sänka hantlarna tillbaka till startpositionen.", "en": "Inhale and slowly begin to lower the dumbbells back to the starting position."}, {"sv": "Upprepa önskat antal repetitioner, byt sedan ben och upprepa.", "en": "Repeat for the desired number of repetitions, then switch legs and repeat."}]$instr$::jsonb WHERE name = 'Hantelcurl i storkposition' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Ställ in bänken i 45 graders lutning.", "en": "Adjust the bench to a 45-degree incline."}, {"sv": "Ligg på mage på bänken med bröstet och magen vilande mot den.", "en": "Lie face down on the bench with your chest and stomach resting against it."}, {"sv": "Håll en hantel i varje hand med handflatorna vända nedåt och armarna helt utsträckta.", "en": "Hold a dumbbell in each hand with your palms facing down and your arms fully extended."}, {"sv": "Håll överarmarna stilla, andas ut och curla vikterna medan du spänner bicepsen.", "en": "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps."}, {"sv": "Fortsätt lyfta vikterna tills bicepsen är helt sammandragen och hantlarna är i axelhöjd.", "en": "Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level."}, {"sv": "Håll den sammandragna positionen en kort stund medan du klämmer åt bicepsen.", "en": "Hold the contracted position for a brief pause as you squeeze your biceps."}, {"sv": "Andas in och börja långsamt sänka hantlarna tillbaka till startpositionen.", "en": "Inhale and slowly begin to lower the dumbbells back to the starting position."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Hantelcurl liggande på lutande bänk' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Placera två hantlar på golvet axelbrett isär och grip handtagen i hög planka, fötterna mellan höftbrett och axelbrett, bålen spänd och handlederna neutrala.", "en": "Place two dumbbells on the floor shoulder-width apart and grip the handles in a high plank; feet hip–shoulder width, core braced, wrists neutral."}, {"sv": "Sänk dig i en kontrollerad armhävning och håll en rak linje från huvud till hälar.", "en": "Lower into a controlled push-up, keeping a straight line from head to heels."}, {"sv": "Flytta vikten något och ro höger hantel mot revbenen utan att rotera överkroppen, sätt tillbaka den i golvet och upprepa med vänster.", "en": "Shift weight slightly and row the right dumbbell toward your ribs without rotating the torso; return it to the floor and repeat with the left."}, {"sv": "Hoppa eller kliv med fötterna till utsidan av hantlarna, håll ryggen plan och höfterna nere.", "en": "Jump or step your feet to the outside of the dumbbells, keeping your back flat and hips down."}, {"sv": "Tryck genom ben och höfter för att frivända hantlarna till axlarna, fånga dem med armbågarna framåt i en halv knäböj.", "en": "Drive through the legs and hips to clean the dumbbells to the shoulders, catching with elbows forward in a partial squat."}, {"sv": "Stå upprätt och pressa hantlarna över huvudet tills armarna är helt utsträckta och revbenen hålls nere.", "en": "Stand tall and press the dumbbells overhead until arms are fully extended and ribs stay down."}, {"sv": "Sänk hantlarna tillbaka till axlarna och fäll sedan i höften för att placera dem i golvet med neutral rygg.", "en": "Lower the dumbbells back to the shoulders, then hinge to place them on the floor with a neutral spine."}, {"sv": "Sparka eller kliv tillbaka med fötterna till plankpositionen och upprepa för nästa repetition.", "en": "Kick or step your feet back to the plank position and repeat for the next rep."}]$instr$::jsonb WHERE name = 'Hantelkomplex (armhävning, rodd, frivändning, press)' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Stå med fötterna axelbrett isär och håll en hantel i varje hand med handflatorna vända mot kroppen.", "en": "Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body."}, {"sv": "Håll ryggen rak och spänn bålen.", "en": "Keep your back straight and engage your core."}, {"sv": "Lyft armarna ut åt sidorna tills de är parallella med golvet, med en lätt böj i armbågarna.", "en": "Raise your arms out to the sides until they are parallel to the floor, keeping a slight bend in your elbows."}, {"sv": "Pausa ett ögonblick i toppläget och sänk sedan långsamt tillbaka armarna till startpositionen.", "en": "Pause for a moment at the top, then slowly lower your arms back down to the starting position."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Hantellyft' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Ligg plant på en bänk med fötterna i golvet och ryggen tryckt mot bänken.", "en": "Lie flat on a bench with your feet flat on the ground and your back pressed against the bench."}, {"sv": "Håll en hantel i varje hand med neutralt grepp (handflatorna mot varandra) och armarna sträckta rakt upp över bröstet.", "en": "Hold a dumbbell in each hand with a neutral grip (palms facing each other) and your arms extended straight up over your chest."}, {"sv": "Sänk långsamt hantlarna ner mot bröstet och håll armbågarna nära kroppen.", "en": "Slowly lower the dumbbells down towards your chest, keeping your elbows close to your body."}, {"sv": "Pausa ett ögonblick i bottenläget och pressa sedan tillbaka hantlarna till startpositionen tills armarna är helt sträckta.", "en": "Pause for a moment at the bottom, then push the dumbbells back up to the starting position, fully extending your arms."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Hantelpress med neutralt grepp' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Ligg platt på en bänk med fötterna platt i golvet och knäna böjda.", "en": "Lie flat on a bench with your feet flat on the ground and your knees bent."}, {"sv": "Håll en hantel i varje hand med överhandsgrepp och handflatorna vända mot fötterna.", "en": "Hold a dumbbell in each hand with an overhand grip, palms facing towards your feet."}, {"sv": "Sträck armarna rakt upp mot taket med en lätt böj i armbågarna.", "en": "Extend your arms straight up towards the ceiling, keeping a slight bend in your elbows."}, {"sv": "Sänk hantlarna långsamt mot bröstet och låt armbågarna gå ut åt sidorna.", "en": "Slowly lower the dumbbells towards your chest, allowing your elbows to flare out to the sides."}, {"sv": "Pausa ett ögonblick i bottenläget och pressa sedan tillbaka hantlarna till startpositionen.", "en": "Pause for a moment at the bottom, then push the dumbbells back up to the starting position."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Hantelpress med omvänt grepp' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Ligg plant på en bänk med fötterna i golvet och ryggen tryckt mot bänken.", "en": "Lie flat on a bench with your feet flat on the ground and your back pressed against the bench."}, {"sv": "Håll en hantel i varje hand med överhandsgrepp och handflatorna vända bort från dig.", "en": "Hold a dumbbell in each hand with an overhand grip, palms facing away from you."}, {"sv": "Sträck armarna rakt upp över bröstet med en lätt böj i armbågarna.", "en": "Extend your arms straight up over your chest, keeping a slight bend in your elbows."}, {"sv": "Sänk hantlarna ner mot bröstet med armbågarna nära kroppen.", "en": "Lower the dumbbells down towards your chest, keeping your elbows close to your body."}, {"sv": "Medan du sänker hantlarna vrider du handlederna så att handflatorna är vända mot dig i botten av rörelsen.", "en": "As you lower the dumbbells, twist your wrists so that your palms face towards you at the bottom of the movement."}, {"sv": "Pausa ett ögonblick i botten och vänd sedan rörelsen genom att pressa hantlarna tillbaka upp till startpositionen.", "en": "Pause for a moment at the bottom, then reverse the movement by pressing the dumbbells back up to the starting position."}, {"sv": "Medan du pressar upp hantlarna vrider du tillbaka handlederna till utgångsläget med handflatorna vända bort från dig.", "en": "As you press the dumbbells up, twist your wrists back to the starting position with palms facing away from you."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Hantelpress med rotation' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Sitt på en plan bänk med en hantel i varje hand vilande på låren.", "en": "Sit on a flat bench with a dumbbell in each hand, resting on your thighs."}, {"sv": "Använd låren för att hjälpa till att lyfta hantlarna, en i taget, så att du kan hålla dem framför dig i axelbredd.", "en": "Using your thighs to help raise the dumbbells, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width."}, {"sv": "Väl i axelbredd, rotera handlederna framåt så att handflatorna pekar bort från dig. Detta är din startposition.", "en": "Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position."}, {"sv": "Andas in och sänk långsamt hantlarna mot sidorna tills de är ungefär i höjd med bröstet.", "en": "As you breathe in, slowly lower the dumbbells to your side until they are about level with your chest."}, {"sv": "Andas ut och använd triceps för att lyfta hantlarna tillbaka till startpositionen. Se till att bara använda triceps och ta inte hjälp av underarmar eller biceps för att lyfta hantlarna.", "en": "As you exhale, use your triceps to lift the dumbbells back to the starting position. Make sure to use only your triceps and do not use your forearms or biceps to help lift the dumbbells."}, {"sv": "Efter en sekunds paus i den kontraherade positionen, upprepa rörelsen föreskrivet antal repetitioner.", "en": "After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions."}]$instr$::jsonb WHERE name = 'Hantelpress smalt grepp' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Ligg plant på en bänk med huvudet vid ena änden och fötterna stadigt i golvet.", "en": "Lie flat on a bench with your head at one end and your feet firmly on the ground."}, {"sv": "Håll en hantel med båda händerna och sträck armarna rakt upp ovanför bröstet.", "en": "Hold a dumbbell with both hands and extend your arms straight above your chest."}, {"sv": "Håll armarna raka och sänk långsamt hanteln bakom huvudet i en bågrörelse.", "en": "Keeping your arms straight, slowly lower the dumbbell behind your head in an arc motion."}, {"sv": "Pausa ett ögonblick i botten och lyft sedan hanteln tillbaka till startpositionen.", "en": "Pause for a moment at the bottom, then raise the dumbbell back to the starting position."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Hantelpullover runt huvudet' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Ställ in en lutande bänk i 45 graders vinkel.", "en": "Set up an incline bench at a 45-degree angle."}, {"sv": "Sitt på bänken med bröstet mot ryggstödet och fötterna platt i golvet.", "en": "Sit on the bench with your chest against the backrest and your feet flat on the ground."}, {"sv": "Håll en hantel i varje hand med underhandsgrepp.", "en": "Hold a dumbbell in each hand with an underhand grip."}, {"sv": "Luta dig framåt och låt armarna hänga rakt ner, helt utsträckta.", "en": "Lean forward and let your arms hang straight down, fully extended."}, {"sv": "Dra hantlarna upp mot bröstet och kläm ihop skulderbladen.", "en": "Pull the dumbbells up towards your chest, squeezing your shoulder blades together."}, {"sv": "Pausa ett ögonblick i toppläget och sänk sedan långsamt tillbaka hantlarna till startpositionen.", "en": "Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Hantelrodd på lutande bänk med omvänt grepp' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Stå i kampställning med den främre foten fram, händerna uppe och större delen av vikten på det bakre benet.", "en": "Stand in fighting stance with the lead foot forward, hands up, and most of your weight on the rear leg."}, {"sv": "Pivotera på den bakre stödfoten för att öppna höfterna och rikta hälen något utåt.", "en": "Pivot on the rear/support foot to open the hips and point the heel slightly outward."}, {"sv": "Ladda det främre benet: lyft knät till höfthöjd med låret något ut åt sidan, böj vristen uppåt så att tårna dras bakåt.", "en": "Chamber the lead leg: lift the knee to hip height with the thigh slightly out to the side; dorsiflex the ankle so the toes pull back."}, {"sv": "Sträck ut underbenet en bit förbi målet, svep sedan foten inåt över mittlinjen i en krokformad båge och träffa med hälen eller sulans kant.", "en": "Extend the lower leg a bit past the target, then sweep the foot inward across the midline in a hooking arc, striking with the heel/edge of the sole."}, {"sv": "Håll bålen spänd och överkroppen upprätt, översträck inte knät i utsträckt läge.", "en": "Keep the core braced and the torso upright; do not hyperextend the knee at extension."}, {"sv": "Dra omedelbart tillbaka benet längs samma bana och sätt ner foten i startställningen.", "en": "Retract the leg immediately along the same path and place the foot down to the starting stance."}, {"sv": "Upprepa med kontrollerade repetitioner, byt sedan sida.", "en": "Repeat for controlled reps, then switch sides."}]$instr$::jsonb WHERE name = 'Hook kick med främre benet' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Stå med fötterna axelbrett isär.", "en": "Stand with your feet shoulder-width apart."}, {"sv": "Böj knäna och sänk kroppen till en knäböjsposition.", "en": "Bend your knees and lower your body into a squat position."}, {"sv": "Sväng armarna bakåt för att få fart.", "en": "Swing your arms back for momentum."}, {"sv": "Hoppa explosivt framåt och sträck ut höfter, knän och vrister.", "en": "Jump forward explosively, extending your hips, knees, and ankles."}, {"sv": "Landa mjukt på trampdynorna och gå direkt vidare till nästa hopp.", "en": "Land softly on the balls of your feet and immediately go into the next jump."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Hopp framåt' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Ställ in maskinens säte så att knäna är i 90 graders vinkel när fötterna står på fotplattan.", "en": "Adjust the seat of the machine so that your knees are at a 90-degree angle when your feet are on the footplate."}, {"sv": "Sitt i maskinen med ryggen mot ryggstödet och fötterna axelbrett isär på fotplattan.", "en": "Sit on the machine with your back against the backrest and your feet shoulder-width apart on the footplate."}, {"sv": "Placera händerna på handtagen eller maskinens sidor för stabilitet.", "en": "Place your hands on the handles or sides of the machine for stability."}, {"sv": "Tryck fotplattan bort från kroppen genom att sträcka ut benet, håll ryggen mot ryggstödet.", "en": "Push the footplate away from your body by extending your leg, keeping your back against the backrest."}, {"sv": "Pausa ett ögonblick i det helt utsträckta läget, böj sedan långsamt benet för att återgå till startpositionen.", "en": "Pause for a moment at the fully extended position, then slowly bend your leg to return to the starting position."}, {"sv": "Upprepa önskat antal repetitioner och byt sedan ben.", "en": "Repeat for the desired number of repetitions, then switch legs."}]$instr$::jsonb WHERE name = 'Horisontell enbens benpress i maskin' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Ligg plant på en bänk med en hantel i varje hand, handflatorna vända mot varandra.", "en": "Lie flat on a bench with a dumbbell in each hand, palms facing each other."}, {"sv": "Sträck armarna rakt upp över bröstet, med en lätt böj i armbågarna.", "en": "Extend your arms straight up over your chest, with a slight bend in your elbows."}, {"sv": "Behåll en lätt böj i armbågarna och sänk hantlarna ut åt sidorna i en vid båge tills du känner en stretch i bröstet.", "en": "Keeping a slight bend in your elbows, lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest."}, {"sv": "Pausa ett ögonblick, vänd sedan rörelsen och för tillbaka hantlarna till startpositionen.", "en": "Pause for a moment, then reverse the movement and bring the dumbbells back to the starting position."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Hyght flyes med hantlar' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Justera hyperextensionsbänken så att höfterna vilar bekvämt mot dynan och fötterna sitter fast.", "en": "Adjust the hyperextension bench so that your hips are resting comfortably on the pad and your feet are secured."}, {"sv": "Korsa armarna över bröstet eller placera händerna bakom huvudet.", "en": "Cross your arms over your chest or place your hands behind your head."}, {"sv": "Sänk långsamt överkroppen mot golvet med rak rygg.", "en": "Slowly lower your upper body towards the ground while keeping your back straight."}, {"sv": "Pausa ett ögonblick i botten, lyft sedan överkroppen tills den är i linje med benen.", "en": "Pause for a moment at the bottom, then raise your upper body back up until it is in line with your legs."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Hyperextension på bänk' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Stå med en fot framför den andra, händerna uppe, fötterna höftbrett isär, bålen spänd och blicken framåt.", "en": "Stand in a staggered stance with hands up, feet hip‑width, core braced, and eyes forward."}, {"sv": "Lyft det främre knät mot bröstet (höftböjning) och håll vristen flexad så att tårna pekar uppåt.", "en": "Lift the lead knee toward the chest (hip flex), keeping the ankle dorsiflexed so toes point up."}, {"sv": "Driv höfterna framåt och sträck knät för att trycka rakt ut, träffa med mitten av hälen.", "en": "Drive the hips forward and extend the knee to push straight out, striking with the center of the heel."}, {"sv": "Håll stödfoten stadigt i golvet och bäckenet i våg, undvik att luta dig bakåt eller rotera höfterna.", "en": "Keep the supporting foot rooted and pelvis level; avoid leaning back or rotating the hips."}, {"sv": "Stanna strax innan knät låser sig, böj sedan omedelbart knät och dra tillbaka benet.", "en": "Stop short of locking the knee, then immediately re‑chamber by bending the knee and pulling the leg back."}, {"sv": "Sätt tillbaka foten i golvet under kontroll och återta din ställning.", "en": "Return the foot to the floor under control and reset in your stance."}, {"sv": "Upprepa önskat antal repetitioner, byt sedan sida så att båda benen tränas.", "en": "Repeat for reps, then switch sides to train both legs."}]$instr$::jsonb WHERE name = 'Hälspark' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Häng i en pull-up-stång med helt sträckta armar och handflatorna vända bort från dig.", "en": "Hang from a pull-up bar with your arms fully extended and your palms facing away from you."}, {"sv": "Spänn bålen och lyft benen framför dig, håll dem raka.", "en": "Engage your core and lift your legs up in front of you, keeping them straight."}, {"sv": "Fortsätt lyfta tills benen är parallella med golvet eller något högre.", "en": "Continue lifting until your legs are parallel to the ground or slightly higher."}, {"sv": "Pausa ett ögonblick i toppen och sänk sedan långsamt benen tillbaka till startpositionen.", "en": "Pause for a moment at the top, then slowly lower your legs back down to the starting position."}, {"sv": "Upprepa i önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Hängande ben och höftlyft med vikt' AND user_id IS NULL;
