UPDATE exercises SET instructions = $instr$[{"sv": "Börja med att hänga i en pull-up-stång med överhandsgrepp, händerna något bredare än axelbrett.", "en": "Start by hanging from a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart."}, {"sv": "Spänn bålen och använd en svingande rörelse för att skapa fart.", "en": "Engage your core and use a swinging motion to generate momentum."}, {"sv": "När du svingar framåt drar du bröstet mot stången och startar rörelsen med lats och biceps.", "en": "As you swing forward, pull your chest towards the bar, using your lats and biceps to initiate the movement."}, {"sv": "Fortsätt uppåt tills bröstet når stången, övergå sedan till en dipposition genom att trycka ner mot stången och sträcka armarna.", "en": "Continue the upward motion until your chest reaches the bar, then transition into a dip position by pushing down on the bar and extending your arms."}, {"sv": "Sänk dig tillbaka till startpositionen genom att böja armarna och kontrollera nedgången.", "en": "Lower yourself back down to the starting position by bending your arms and controlling the descent."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Kipping muscle up' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Börja i hög plankposition med händerna rakt under axlarna och kroppen i en rak linje.", "en": "Start in a high plank position with your hands directly under your shoulders and your body in a straight line."}, {"sv": "Sänk kroppen mot golvet genom att böja armbågarna, håll dem nära sidorna.", "en": "Lower your body towards the ground by bending your elbows, keeping them close to your sides."}, {"sv": "Medan du sänker dig, rotera kroppen åt vänster och sträck vänster arm rakt ut åt sidan.", "en": "As you lower, rotate your body to the left, extending your left arm straight out to the side."}, {"sv": "Pressa dig tillbaka upp till startpositionen medan du roterar kroppen till mitten.", "en": "Push back up to the starting position, while rotating your body to the center."}, {"sv": "Upprepa armhävningen, denna gång roterar du kroppen åt höger och sträcker ut höger arm åt sidan.", "en": "Repeat the push-up, this time rotating your body to the right and extending your right arm out to the side."}, {"sv": "Fortsätt växla sida för varje repetition.", "en": "Continue alternating sides with each repetition."}]$instr$::jsonb WHERE name = 'Klockarmhävning' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Stå med fötterna bredare än axelbrett isär och tårna lätt utåtvridna.", "en": "Stand with your feet wider than shoulder-width apart, toes pointing slightly outward."}, {"sv": "Håll skivstången över övre delen av ryggen, vilande på trapezius eller bakre delen av axlarna.", "en": "Hold the barbell across your upper back, resting it on your traps or rear delts."}, {"sv": "Spänn bålen och håll bröstet uppe medan du sänker dig ner i en knäböj genom att skjuta höfterna bakåt och böja knäna.", "en": "Engage your core and keep your chest up as you lower your body down into a squat, pushing your hips back and bending your knees."}, {"sv": "Sänk dig tills låren är parallella med golvet, eller så lågt du bekvämt kan komma.", "en": "Lower until your thighs are parallel to the ground, or as low as you can comfortably go."}, {"sv": "Pausa ett ögonblick i botten och pressa sedan genom hälarna för att återgå till startpositionen.", "en": "Pause for a moment at the bottom, then push through your heels to return to the starting position."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Knäböj bred fotställning' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Stå med fötterna axelbrett isär, tårna lätt utåtvridna.", "en": "Stand with your feet shoulder-width apart, toes slightly turned out."}, {"sv": "Placera skivstången på övre delen av ryggen, vilande på trapezius.", "en": "Place the barbell on your upper back, resting it on your traps."}, {"sv": "Spänn bålen och håll bröstet uppe när du börjar gå ned i knäböj, skjut höfterna bakåt och böj knäna.", "en": "Engage your core and keep your chest up as you begin to squat down, pushing your hips back and bending your knees."}, {"sv": "Sänk dig tills låren är parallella med golvet, eller så lågt du bekvämt kan komma.", "en": "Lower yourself until your thighs are parallel to the ground, or as low as you can comfortably go."}, {"sv": "Pressa genom hälarna för att resa dig upp igen och sträck ut höfter och knän.", "en": "Drive through your heels to stand back up, extending your hips and knees."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Knäböj high bar' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Ställ in smithmaskinen med stången på en höjd som passar din knäböj.", "en": "Set up the smith machine with the barbell at an appropriate height for your squat."}, {"sv": "Stå med fötterna axelbrett isär och tårna lätt utåtvinklade.", "en": "Stand with your feet shoulder-width apart, toes slightly turned out."}, {"sv": "Placera dig under stången så att den vilar på övre delen av kappmuskeln och axlarna.", "en": "Position yourself under the barbell, resting it on your upper traps and shoulders."}, {"sv": "Greppa stången med ett brett grepp, något bredare än axelbrett.", "en": "Grip the barbell with a wide grip, slightly wider than shoulder-width apart."}, {"sv": "Spänn bålen, lyft ur stången och kliv bakåt så att du går fritt från stället.", "en": "Engage your core and unrack the barbell, stepping back to clear the rack."}, {"sv": "Håll bröstet lyft och ryggen rak, och inled knäböjen genom att böja i höfter och knän.", "en": "Keeping your chest up and back straight, initiate the squat by bending at the hips and knees."}, {"sv": "Sänk kroppen tills låren är parallella med golvet eller något djupare.", "en": "Lower your body until your thighs are parallel to the ground or slightly below."}, {"sv": "Pausa ett ögonblick i botten och tryck sedan genom hälarna tillbaka till startpositionen.", "en": "Pause for a moment at the bottom, then drive through your heels to return to the starting position."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Knäböj i smithmaskin' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Stå med fötterna axelbrett isär och skivstången vilande på övre delen av ryggen.", "en": "Stand with your feet shoulder-width apart and the barbell resting on your upper back."}, {"sv": "Håll bröstet uppe och bålen spänd medan du långsamt sänker kroppen genom att böja knäna och skjuta höfterna bakåt.", "en": "Keeping your chest up and core engaged, slowly lower your body by bending your knees and pushing your hips back."}, {"sv": "Fortsätt sänka tills låren är parallella med golvet eller något lägre.", "en": "Continue lowering until your thighs are parallel to the ground or slightly below."}, {"sv": "Pausa ett ögonblick och pressa sedan genom hälarna för att återgå till startpositionen.", "en": "Pause for a moment, then push through your heels to return to the starting position."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Knäböj low bar' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Ställ in smithmaskinen med stången på en höjd där du bekvämt kan vila den på övre delen av ryggen.", "en": "Set up the smith machine with the barbell at a height that allows you to comfortably rest it on your upper back."}, {"sv": "Stå med fötterna axelbrett isär och tårna lätt utåtvinklade.", "en": "Stand with your feet shoulder-width apart, toes slightly turned outwards."}, {"sv": "Kliv in under stången och placera den över övre delen av ryggen, vilande på kappmuskeln.", "en": "Step under the bar and position it across your upper back, resting it on your traps."}, {"sv": "Greppa stången med händerna något bredare än axelbrett.", "en": "Grip the bar with your hands slightly wider than shoulder-width apart."}, {"sv": "Lyft ur stången genom att sträcka på benen och kliva bort från stället.", "en": "Unrack the bar by straightening your legs and stepping back from the rack."}, {"sv": "Ta ett djupt andetag och spänn bålen.", "en": "Take a deep breath and brace your core."}, {"sv": "Inled knäböjen genom att skjuta höfterna bakåt och böja knäna.", "en": "Initiate the squat by pushing your hips back and bending your knees."}, {"sv": "Sänk kroppen tills låren är parallella med golvet eller något djupare.", "en": "Lower your body until your thighs are parallel to the ground or slightly below."}, {"sv": "Håll bröstet lyft och ryggen rak genom hela rörelsen.", "en": "Keep your chest up and your back straight throughout the movement."}, {"sv": "Tryck genom hälarna för att resa dig igen, sträck ut höfter och knän.", "en": "Drive through your heels to stand back up, extending your hips and knees."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Knäböj låg stångplacering i smithmaskin' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Justera stödet så att vristerna sitter tätt under rullen och vaderna har kontakt med den bakre dynan. Stå upprätt på plattan med fötterna höftbrett isär och tårna framåt.", "en": "Adjust the support so your ankles are snug under the roller and your calves contact the rear pad; stand tall with feet hip-width and toes forward on the platform."}, {"sv": "Håll en hantel vertikalt mot bröstet (goblet) eller två hantlar vid axlarna. Spänn bålen och håll ryggen neutral.", "en": "Hold a dumbbell vertically at your chest (goblet) or two dumbbells at your shoulders; brace your core and keep a neutral spine."}, {"sv": "Andas in och inled nedåtfasen genom att böja knäna framåt. Låt dem följa linjen över andra och tredje tån, medan höfterna hålls relativt sträckta och överkroppen upprätt.", "en": "Inhale and initiate the descent by bending your knees forward, allowing them to track over your second–third toes while keeping hips relatively extended and torso upright."}, {"sv": "Håll hälarna nere och låt smalbenen styras av stödet. Låt inte ländryggen rundas eller knäna falla inåt.", "en": "Keep heels down and shins guided by the support; do not let the lower back round or knees cave inward."}, {"sv": "Sänk dig kontrollerat tills låren är parallella med golvet eller till ett djup som känns bekvämt, utan att tappa trycket i fötterna eller ryggens position.", "en": "Lower under control until thighs reach parallel or your comfortable depth without losing foot pressure or spinal position."}, {"sv": "Tryck genom mellanfoten för att sträcka knäna och återgå till stående. Andas ut när du passerar den tyngsta punkten.", "en": "Drive through the mid-foot to extend the knees and return to standing, exhaling as you pass the sticking point."}, {"sv": "Pausa kort, spänn bålen på nytt och upprepa önskat antal reps med ett jämnt och kontrollerat tempo.", "en": "Pause briefly, reset your brace, and repeat for the target reps with smooth, controlled tempo."}]$instr$::jsonb WHERE name = 'Knäböj med hantel och stöd' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Stå med fötterna axelbrett isär och håll en hantel i varje hand längs sidorna.", "en": "Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides."}, {"sv": "Håll bröstet upp och bålen spänd och sänk kroppen genom att böja i knän och höfter, som om du skulle sätta dig på en stol.", "en": "Keeping your chest up and core engaged, lower your body down by bending at the knees and hips, as if sitting back into a chair."}, {"sv": "Fortsätt sänka tills låren är parallella med golvet, eller så lågt du bekvämt kan komma.", "en": "Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go."}, {"sv": "Pausa ett ögonblick i bottenläget och tryck sedan ifrån genom hälarna för att återgå till startpositionen.", "en": "Pause for a moment at the bottom, then push through your heels to return to the starting position."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Knäböj med hantlar' AND user_id IS NULL;
