UPDATE exercises SET instructions = $instr$[{"sv": "Börja knästående på golvet med fötterna höftbrett isär och tårna pekande framåt.", "en": "Start by kneeling on the ground with your feet hip-width apart and your toes pointing forward."}, {"sv": "Håll en skivstång över övre delen av ryggen, vilande på axlarna.", "en": "Hold a barbell across your upper back, resting it on your shoulders."}, {"sv": "Spänn bål och säte och hoppa sedan explosivt upp i luften genom att sträcka ut höfter och knän.", "en": "Engage your core and glutes, then explosively jump up into the air, extending your hips and knees."}, {"sv": "När du hoppar trycker du genom tårna och sträcker ut fotleder, knän och höfter helt.", "en": "As you jump, push through your toes and fully extend your ankles, knees, and hips."}, {"sv": "Landa mjukt på golvet igen och böj knäna för att ta upp stöten.", "en": "Land softly back on the ground, bending your knees to absorb the impact."}, {"sv": "Gå direkt vidare till nästa repetition och upprepa hopprörelsen.", "en": "Immediately go into the next repetition, repeating the jump squat motion."}]$instr$::jsonb WHERE name = 'Knäböj med hopp från knästående' AND user_id IS NULL;
