UPDATE exercises SET instructions = $instr$[{"sv": "Lägg skivstången över övre delen av trapezius med axelbrett grepp. Stå 15 till 30 cm framför en stadig plattform, med fötterna höftbrett isär och tårna lätt utåtvridna.", "en": "Rack the barbell across your upper traps with a shoulder-width grip; stand 15–30 cm in front of a sturdy step, feet hip-width and toes slightly out."}, {"sv": "Spänn bålen, håll ryggen neutral och sjunk ner i en kvarts till halv knäböj.", "en": "Brace your core, set a neutral spine, and sit into a quarter–half squat."}, {"sv": "Tryck ifrån med fötterna och hoppa upp på plattformen. Landa mjukt på båda fötterna med knäna i linje över tårna och hälarna nere.", "en": "Drive through your feet and jump onto the step, landing softly on both feet with knees tracking over toes and heels down."}, {"sv": "Ställ dig upprätt på plattformen, kliv sedan ner med ena foten till golvet och sänk dig i ett kontrollerat utfall bakåt (främre smalbenet lodrätt, bakre knät under höften).", "en": "Stand tall on the step, then step one foot back to the floor and lower into a controlled rear lunge (front shin vertical, back knee under hip)."}, {"sv": "Pressa genom främre hälen för att komma tillbaka till stående på golvet i startpositionen.", "en": "Push through the front heel to return to standing on the floor at the start position."}, {"sv": "Upprepa hoppet och växla utfallsben varje rep, med upprätt överkropp och stabil stång.", "en": "Repeat the jump and alternate the lunge leg each rep while keeping the torso upright and the bar stable."}, {"sv": "Använd en låg plattform och lätt vikt. Avbryt setet om du tappar kontrollen i landningen eller balansen.", "en": "Use a low step and light load; stop the set if landing control or balance is lost."}]$instr$::jsonb WHERE name = 'Knäböjshopp och utfall bakåt med skivstång' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Fäst ett rep i en kabelmaskin i midjehöjd.", "en": "Attach a rope to a cable machine at waist height."}, {"sv": "Stå vänd mot kabelmaskinen med fötterna axelbrett isär.", "en": "Stand facing the cable machine with your feet shoulder-width apart."}, {"sv": "Böj knäna och sänk dig ned i en knäböjsposition, håll ryggen rak och bröstet uppe.", "en": "Bend your knees and lower your body into a squat position, keeping your back straight and chest up."}, {"sv": "Greppa repet med överhandsgrepp, händerna axelbrett isär.", "en": "Grasp the rope with an overhand grip, with your hands shoulder-width apart."}, {"sv": "Spänn bålen och dra repet mot kroppen, pressa ihop skulderbladen.", "en": "Engage your core and pull the rope towards your body, squeezing your shoulder blades together."}, {"sv": "Håll armbågarna nära kroppen och fortsätt dra tills händerna når bröstet.", "en": "Keep your elbows close to your body and continue pulling until your hands reach your chest."}, {"sv": "Pausa ett ögonblick i toppen av rörelsen, släpp sedan långsamt efter och sträck ut armarna till startpositionen.", "en": "Pause for a moment at the top of the movement, then slowly release the rope and extend your arms back to the starting position."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Knäböjsrodd i kabel med rep' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Stå med fötterna axelbrett isär och händerna på höfterna.", "en": "Stand with your feet shoulder-width apart and your hands on your hips."}, {"sv": "Böj knäna lätt och lyft hälarna från golvet, balansera på framfötterna.", "en": "Bend your knees slightly and lift your heels off the ground, balancing on the balls of your feet."}, {"sv": "Håll knäna böjda och rotera dem i en cirkelrörelse, först medurs och sedan moturs.", "en": "Keeping your knees bent, rotate your knees in a circular motion, first clockwise and then counterclockwise."}, {"sv": "Utför rörelsen önskat antal repetitioner.", "en": "Perform the movement for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Knäcirklar' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Börja med att stå med fötterna axelbrett isär.", "en": "Start by standing with your feet shoulder-width apart."}, {"sv": "Böj knäna och sänk kroppen ner i en knäböjsposition.", "en": "Bend your knees and lower your body down into a squat position."}, {"sv": "När du går ner i knäböjen, dra knäna upp mot bröstet och krama om dem med armarna.", "en": "As you squat down, bring your knees up towards your chest and hug them with your arms."}, {"sv": "Håll positionen ett ögonblick och återgå sedan långsamt till startpositionen.", "en": "Hold this position for a moment, then slowly return to the starting position."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Knän mot bröstet' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Stå på knä på golvet med knäna höftbrett isär och tårna pekande bakåt.", "en": "Kneel on the ground with your knees hip-width apart and your toes pointing back."}, {"sv": "Sträck armarna över huvudet och fläta ihop fingrarna.", "en": "Extend your arms overhead and interlace your fingers."}, {"sv": "Håll ryggen rak och luta dig långsamt åt höger tills du känner en stretch i vänster lats.", "en": "Keeping your back straight, slowly lean to the right side, feeling a stretch in your left lat muscle."}, {"sv": "Håll stretchen i 20 till 30 sekunder och återgå sedan till startpositionen.", "en": "Hold the stretch for 20-30 seconds, then return to the starting position."}, {"sv": "Upprepa stretchen på vänster sida, luta dig åt vänster och känn stretchen i höger lats.", "en": "Repeat the stretch on the left side, leaning to the left and feeling a stretch in your right lat muscle."}, {"sv": "Fortsätt växla sida önskat antal repetitioner.", "en": "Continue alternating sides for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Knästående latsstretch' AND user_id IS NULL;
