UPDATE exercises SET instructions = $instr$[{"sv": "Inta kampställning med bakre foten bakom dig, mjuka knän, händerna uppe och bålen spänd.", "en": "Adopt a fighting stance with the rear foot behind, knees soft, hands up, and core braced."}, {"sv": "Pivotera på främre fotens trampdyna för att öppna höfterna, håll överkroppen upprätt.", "en": "Pivot on the ball of the lead foot to open the hips while keeping the torso tall."}, {"sv": "Ladda bakre benet genom att lyfta knät ut åt sidan (höftabduktion) med knät böjt och foten uppåtböjd.", "en": "Chamber the rear leg by lifting the knee out to the side (hip abduction) with the knee bent and foot dorsiflexed."}, {"sv": "Svep underbenet inåt i en horisontell båge, för höften inåt för att kroka målet och träffa med hälen eller fotens baksida.", "en": "Sweep the lower leg inward in a horizontal arc, adducting the hip to ‘hook’ the target and striking with the heel or back of the foot."}, {"sv": "Ladda om benet direkt och sätt sedan ner det kontrollerat i utgångsställningen.", "en": "Re-chamber the leg immediately, then place it back to the starting stance under control."}, {"sv": "Andas ut vid sparken, håll stödbenets knä mjukt och undvik att låsa sparkbenets knä eller att överrotera höfterna.", "en": "Exhale on the strike, keep the supporting knee soft, and avoid locking the kicking knee or over-rotating the hips."}]$instr$::jsonb WHERE name = 'Krokspark med bakre benet' AND user_id IS NULL;
