UPDATE exercises SET instructions = $instr$[{"sv": "Stå med fötterna axelbrett isär och håll skivstången med båda händerna framför bröstet.", "en": "Stand with your feet shoulder-width apart and hold the barbell with both hands in front of your chest."}, {"sv": "Böj knäna lätt och rotera överkroppen åt höger, sväng stången ner mot höger höft.", "en": "Bend your knees slightly and rotate your torso to the right, swinging the barbell down towards your right hip."}, {"sv": "När du når botten av rörelsen vänder du snabbt riktning och roterar överkroppen åt vänster, sväng stången upp och tvärs över kroppen mot vänster axel.", "en": "As you reach the bottom of the movement, quickly reverse the motion and rotate your torso to the left, swinging the barbell up and across your body towards your left shoulder."}, {"sv": "Fortsätt den vridande rörelsen växelvis åt båda sidor önskat antal repetitioner.", "en": "Continue this twisting motion, alternating sides, for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Landmine 180' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Sätt en skivstång i en landmine (ena änden förankrad i golvet i en hylsa eller ett hörn) och lasta den fria änden med en viktskiva.", "en": "Set a barbell in a landmine (one end anchored on the floor in a sleeve or corner) and load the free end with a plate."}, {"sv": "Fäst ett neutralgrepp eller V-handtag på stångens lastade ände om det visas, och stå vänd mot förankringen med fötterna ungefär axelbrett isär.", "en": "Attach a neutral-grip or V-handle to the loaded end of the bar if shown, and stand facing the anchor with feet about shoulder-width apart."}, {"sv": "Håll handtaget i höjd med övre bröstet eller främre axeln, med armbågarna intill kroppen och överkroppen upprätt.", "en": "Hold the handle at upper chest or front-shoulder height with your elbows tucked and torso tall."}, {"sv": "Spänn bålen, sitt bakåt och böj knäna för att sänka dig i en kontrollerad knäböj, låt stången följa sin naturliga framåtriktade båge från pivotpunkten.", "en": "Brace your core, sit back and bend your knees to lower into a controlled squat, keeping the bar traveling in its natural forward arc from the pivot."}, {"sv": "Sänk dig tills låren är ungefär parallella med golvet eller så djupt du kan kontrollera, och pressa sedan genom mellanfot och hälar för att resa dig upp igen.", "en": "Descend until your thighs are roughly parallel to the floor or as deep as you can control, then drive through mid-foot and heels to stand back up."}, {"sv": "Håll balansen över fötterna, sträck ut höfter och knän helt i toppläget och upprepa önskat antal repetitioner.", "en": "Stay balanced over your feet, fully extend the hips and knees at the top, and repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Landmine squat' AND user_id IS NULL;
