UPDATE exercises SET instructions = $instr$[{"sv": "Börja i armhävningsposition med händerna rakt under axlarna och kroppen i en rak linje.", "en": "Start in a push-up position with your hands directly under your shoulders and your body in a straight line."}, {"sv": "Sänk kroppen mot golvet genom att böja armbågarna, håll dem nära sidorna.", "en": "Lower your body down towards the ground by bending your elbows, keeping them close to your sides."}, {"sv": "När armbågarna är i 90 graders vinkel sänker du underarmarna till golvet, håll armbågarna rakt under axlarna.", "en": "Once your elbows are at a 90-degree angle, lower your forearms to the ground, keeping your elbows directly under your shoulders."}, {"sv": "Pausa ett ögonblick och pressa sedan genom handflatorna för att lyfta underarmarna tillbaka till startpositionen.", "en": "Pause for a moment, then push through your palms to lift your forearms back up to the starting position."}, {"sv": "Upprepa i önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Modifierad armhävning till underarmarna' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Börja med att hänga i ett räcke med handflatorna vända från dig och helt raka armar.", "en": "Start by hanging from a pull-up bar with your palms facing away from you and your arms fully extended."}, {"sv": "Spänn bålen och dra kroppen upp mot räcket, led rörelsen med bröstet.", "en": "Engage your core and pull your body up towards the bar, leading with your chest."}, {"sv": "När du når toppen av rörelsen växlar du greppet så att handflatorna är vända mot dig.", "en": "As you reach the top of the movement, transition your grip so that your palms are facing towards you."}, {"sv": "Fortsätt dra dig uppåt tills bröstet är ovanför räcket och armarna är helt böjda.", "en": "Continue pulling yourself up until your chest is above the bar and your arms are fully flexed."}, {"sv": "Vänd på rörelsen genom att långsamt sänka dig tillbaka till startpositionen.", "en": "Reverse the movement by slowly lowering yourself back down to the starting position."}, {"sv": "Upprepa i önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Muscle up' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Börja med att hänga i en pull-up-stång med handflatorna vända från dig och händerna något bredare än axelbrett isär.", "en": "Start by hanging from a pull-up bar with your palms facing away from you and your hands slightly wider than shoulder-width apart."}, {"sv": "Spänn bålen och dra kroppen upp mot stången med bröstet först.", "en": "Engage your core and pull your body up towards the bar, leading with your chest."}, {"sv": "När du når toppen av rörelsen växlar du greppet så att handflatorna är vända mot dig.", "en": "As you reach the top of the movement, transition your grip so that your palms are facing towards you."}, {"sv": "Fortsätt dra dig uppåt tills bröstet når stången och pausa sedan ett ögonblick.", "en": "Continue pulling yourself up until your chest reaches the bar, then pause for a moment."}, {"sv": "Sänk dig långsamt tillbaka till startpositionen med kontroll genom hela rörelsen.", "en": "Slowly lower yourself back down to the starting position, maintaining control throughout the movement."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Muscle up med vikt' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Börja med att hänga i en pull-up-stång med handflatorna vända från dig och händerna något bredare än axelbrett isär.", "en": "Start by hanging from a pull-up bar with your palms facing away from you and your hands slightly wider than shoulder-width apart."}, {"sv": "Spänn bålen och dra skulderbladen nedåt och bakåt.", "en": "Engage your core and pull your shoulder blades down and back."}, {"sv": "Böj armbågarna och dra bröstet mot stången med rak kropp.", "en": "Bend your elbows and pull your chest towards the bar, keeping your body straight."}, {"sv": "När bröstet når stången trycker du nedåt med händerna och driver armbågarna bakåt så att kroppen lyfts över stången.", "en": "Once your chest reaches the bar, push down with your hands and drive your elbows back, lifting your body above the bar."}, {"sv": "Pausa i toppen av rörelsen och sänk dig sedan långsamt tillbaka till startpositionen.", "en": "Pause at the top of the movement, then slowly lower yourself back down to the starting position."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Muscle up på stång med vikt' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Börja med att hänga i en vertikal stång med handflatorna vända från dig och helt raka armar.", "en": "Start by hanging from a vertical bar with your palms facing away from you and your arms fully extended."}, {"sv": "Spänn bålen och dra kroppen upp mot stången, led rörelsen med bröstet.", "en": "Engage your core and pull your body up towards the bar, leading with your chest."}, {"sv": "Medan du drar dig uppåt lutar du dig lätt bakåt och för armbågarna mot sidorna.", "en": "As you pull yourself up, lean back slightly and bring your elbows towards your sides."}, {"sv": "Fortsätt dra tills bröstet når stången och armbågarna är helt böjda.", "en": "Continue pulling until your chest reaches the bar and your elbows are fully bent."}, {"sv": "Pausa ett ögonblick i toppen och sänk dig sedan långsamt tillbaka till startpositionen.", "en": "Pause for a moment at the top, then slowly lower yourself back down to the starting position."}, {"sv": "Upprepa i önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Muscle-up på vertikal stång' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Lägg en tjock dyna på golvet. Stå på knä med tårna i golvet, händerna under axlarna och pannan mot dynan.", "en": "Place a thick pad on the floor; kneel with toes tucked, hands under shoulders, and forehead on the pad."}, {"sv": "Dra försiktigt in hakan för att skapa en lång nacke och spänn magen.", "en": "Gently tuck the chin to create a long neck and brace your abs."}, {"sv": "Pressa mot pannan och tårna för att lyfta knäna en aning och höj höfterna till en vinklad position.", "en": "Press into your forehead and toes to lift the knees slightly, raising the hips into a pike."}, {"sv": "Med lätt stöd av händerna flyttar du långsamt kroppen framåt för att belasta pannan utan att nacken viker sig.", "en": "With hands lightly assisting, slowly shift your body forward to load the forehead without collapsing the neck."}, {"sv": "Pausa kort och för sedan kroppen bakåt för att minska belastningen, behåll linjen och andas lugnt.", "en": "Pause briefly, then shift back to reduce load while maintaining alignment and steady breathing."}, {"sv": "Gör små, smärtfria gungningar som repetitioner och håll rörelserna långsamma och kontrollerade.", "en": "Perform small, pain-free rocks for reps, keeping movements slow and controlled."}, {"sv": "Sänk knäna tillbaka till golvet för att avsluta positionen.", "en": "Lower the knees back to the floor to exit the position."}]$instr$::jsonb WHERE name = 'Nackbrygga framliggande' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Ställ in sitsen så att huvuddynan ligger an mot bakhuvudet (inte nacken) och ladda med lätta vikter.", "en": "Adjust seat so the head pad contacts the back of your skull (not the neck) and load light plates."}, {"sv": "Sitt upprätt med bröstet mot dynan, fötterna plant i golvet och ryggraden neutral. Greppa handtagen för stabilitet.", "en": "Sit upright with chest against the pad, feet flat, and spine neutral; grip the handles for stability."}, {"sv": "Börja med hakan lätt indragen och blicken framåt. Undvik att sjunka ihop eller svanka.", "en": "Begin with a slight chin tuck and eyes forward; avoid slouching or arching the low back."}, {"sv": "Andas ut och sträck nacken genom att pressa huvudet bakåt mot dynan tills huvudet är i linje med överkroppen, överdriv inte rörelsen.", "en": "Exhale and extend the neck by pressing the head back into the pad until the head aligns with the torso—do not hyperextend."}, {"sv": "Pausa kort och håll axlarna avslappnade och sänkta.", "en": "Pause briefly while keeping shoulders relaxed and down."}, {"sv": "Andas in och kontrollera återgången genom att böja nacken och föra hakan något mot bröstet inom ett bekvämt rörelseomfång.", "en": "Inhale and control the return by flexing the neck, bringing the chin slightly toward the chest within a comfortable range."}, {"sv": "Rör dig långsamt och mjukt. Avbryt om du känner smärta i nacken, stickningar eller yrsel.", "en": "Move slowly and smoothly; stop if you feel neck pain, tingling, or dizziness."}]$instr$::jsonb WHERE name = 'Nackextension i maskin' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Ställ in sits och dyna så att huvuddynan ligger an mot höger sida av skallen strax ovanför örat med nacken i neutralt läge.", "en": "Adjust seat and pad so the head pad contacts the right side of your skull just above the ear with your neck in neutral."}, {"sv": "Sitt upprätt med fötterna plant i golvet. Greppa maskinens handtag för att stabilisera överkroppen och håll axlarna sänkta.", "en": "Sit tall with feet flat; grip the machine handles to stabilize your torso and keep shoulders down."}, {"sv": "Håll hakan vågrät och blicken framåt. Undvik att rotera huvudet.", "en": "Set chin level and eyes forward; avoid rotating the head."}, {"sv": "Spänn bålen lätt och pressa höger sida av huvudet mot dynan så att örat förs mot axeln.", "en": "Brace lightly and press the right side of your head into the pad, bringing your ear toward your shoulder."}, {"sv": "Arbeta inom ett bekvämt och smärtfritt rörelseomfång. Ryck inte upp axlarna och vrid inte på huvudet.", "en": "Move through a comfortable, pain‑free range; do not shrug or twist."}, {"sv": "Pausa kort i ytterläget och återgå sedan långsamt och kontrollerat till neutralt läge.", "en": "Pause briefly at end range, then return slowly to neutral under control."}, {"sv": "Andas jämnt och håll en jämn spänning. Gör alla reps på höger sida och träna sedan vänster sida för balans.", "en": "Maintain smooth breathing and consistent tension; complete all reps on the right, then train the left for balance."}]$instr$::jsonb WHERE name = 'Nackflexion höger sida i maskin' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Ställ in sitsen så att maskinens ledpunkt är i höjd med nackens bas och ladda med en lämplig vikt.", "en": "Set the seat so the machine’s pivot is level with the base of your neck and load an appropriate plate."}, {"sv": "Placera den vänstra huvuddynan mot skallens beniga sida ovanför örat (inte mot käken eller örat).", "en": "Position the left head pad on the bony side of your skull above the ear (not on the jaw or ear)."}, {"sv": "Sitt upprätt med ryggen mot dynan och fötterna plant i golvet, och greppa handtagen för att stabilisera överkroppen.", "en": "Sit tall with your back against the pad, feet flat, and grip the handles to stabilize your torso."}, {"sv": "Börja med huvudet i neutralt läge, hakan vågrät och axlarna avslappnade, ryck inte upp axlarna.", "en": "Start with your head neutral, chin level, shoulders relaxed—do not shrug."}, {"sv": "Andas ut medan du långsamt böjer nacken åt vänster och för örat mot axeln utan att rotera huvudet.", "en": "Exhale as you slowly flex your neck to the left, bringing your ear toward your shoulder without rotating the head."}, {"sv": "Pausa kort i ett bekvämt ytterläge utan att det klämmer eller gör ont.", "en": "Pause briefly at a comfortable end range without pinching or pain."}, {"sv": "Andas in medan du kontrollerat återgår till neutralt läge, håll rörelsen långsam och nacken i linje.", "en": "Inhale as you return to neutral under control, keeping the motion slow and the neck aligned."}]$instr$::jsonb WHERE name = 'Nackflexion vänster sida i maskin' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Justera sitshöjden i smithmaskinen så att stången är i axelhöjd.", "en": "Adjust the seat height of the smith machine so that the bar is at shoulder level."}, {"sv": "Stå med fötterna axelbrett isär och knäna lätt böjda.", "en": "Stand with your feet shoulder-width apart and your knees slightly bent."}, {"sv": "Greppa stången med överhandsgrepp, något bredare än axelbrett.", "en": "Grasp the bar with an overhand grip, slightly wider than shoulder-width apart."}, {"sv": "Lyft stången från stället och ta ett steg bakåt, behåll en stabil ställning.", "en": "Lift the bar off the rack and step back, maintaining a stable stance."}, {"sv": "Sänk stången ner bakom nacken och håll armbågarna pekande framåt.", "en": "Lower the bar down to the back of your neck, keeping your elbows pointing forward."}, {"sv": "Pressa stången upp över huvudet tills armarna är helt sträckta.", "en": "Press the bar up overhead until your arms are fully extended."}, {"sv": "Pausa ett ögonblick i toppen, sänk sedan långsamt stången tillbaka till startpositionen.", "en": "Pause for a moment at the top, then slowly lower the bar back down to the starting position."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Nackpress i smithmaskin' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Stå eller sitt upprätt med fötterna stadigt i golvet, avslappnade axlar och blicken framåt.", "en": "Stand or sit upright with feet grounded, shoulders relaxed, and eyes forward."}, {"sv": "För att stretcha nackens baksida: placera en eller båda händerna på hjässan och dra försiktigt hakan mot bröstet tills du känner en mild stretch längs nackens baksida.", "en": "For the back-of-neck stretch: place one or both hands on the crown and gently draw the chin toward the chest until you feel a mild stretch along the back of the neck."}, {"sv": "Håll överkroppen lång utan att runda övre ryggen, håll i 15-30 sekunder och andas lugnt.", "en": "Keep your torso tall without rounding the upper back; hold 15–30 seconds and breathe steadily."}, {"sv": "För långsamt tillbaka huvudet till neutralt läge.", "en": "Return the head to neutral slowly."}, {"sv": "För att stretcha nackens framsida: håll händerna lätt som stöd och titta försiktigt uppåt, förläng nackens framsida utan att sjunka ihop eller klämma i nackens baksida.", "en": "For the front-of-neck stretch: keep hands light for support and gently look upward, lengthening the front of the neck without collapsing or pinching the back of the neck."}, {"sv": "Håll i 10-20 sekunder, andas lugnt och återgå sedan till neutralt läge.", "en": "Hold 10–20 seconds, breathing calmly, then return to neutral."}, {"sv": "Upprepa 1-3 gånger per riktning, avbryt om du känner smärta, stickningar eller yrsel.", "en": "Repeat 1–3 times per direction; stop if you feel pain, tingling, or dizziness."}]$instr$::jsonb WHERE name = 'Nackstretch framåt och bakåt' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Stå eller sitt rakt med avslappnade axlar.", "en": "Stand or sit up straight with your shoulders relaxed."}, {"sv": "Luta huvudet åt höger och för höger öra mot höger axel.", "en": "Tilt your head to the right, bringing your right ear towards your right shoulder."}, {"sv": "Placera höger hand på vänster sida av huvudet och tryck försiktigt för att öka stretchen.", "en": "Place your right hand on the left side of your head and gently apply pressure to increase the stretch."}, {"sv": "Håll stretchen i 15-30 sekunder.", "en": "Hold the stretch for 15-30 seconds."}, {"sv": "Upprepa på andra sidan, luta huvudet åt vänster och tryck med vänster hand.", "en": "Repeat on the other side, tilting your head to the left and applying pressure with your left hand."}, {"sv": "Upprepa stretchen 2-3 gånger per sida.", "en": "Repeat the stretch 2-3 times on each side."}]$instr$::jsonb WHERE name = 'Nackstretch med tryck åt sidan' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Stå eller sitt upprätt med avslappnade axlar.", "en": "Stand or sit up straight with your shoulders relaxed."}, {"sv": "Luta huvudet åt ena sidan och för örat mot axeln.", "en": "Tilt your head to one side, bringing your ear towards your shoulder."}, {"sv": "Håll stretchen i 15 till 30 sekunder.", "en": "Hold the stretch for 15-30 seconds."}, {"sv": "Upprepa på andra sidan.", "en": "Repeat on the other side."}, {"sv": "Gör 2 till 4 set per sida.", "en": "Perform 2-4 sets on each side."}]$instr$::jsonb WHERE name = 'Nackstretch åt sidan' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Stå eller sitt upprätt med fötterna höftbrett isär, bröstet lyft och axlarna avslappnade och sänkta.", "en": "Stand or sit upright with feet hip-width apart, chest tall, and shoulders relaxed and down."}, {"sv": "Håll blicken framåt och hakan i våg, med neutral nacke.", "en": "Keep your gaze forward and chin level (neutral neck)."}, {"sv": "Luta långsamt huvudet åt höger och för höger öra mot höger axel utan att lyfta eller rycka upp axeln.", "en": "Slowly tilt your head to the right, bringing your right ear toward your right shoulder without lifting or shrugging the shoulder."}, {"sv": "Stanna vid en mild stretch på vänster sida av nacken och andas lugnt, håll i 15-30 sekunder.", "en": "Stop at a mild stretch on the left side of the neck and breathe steadily; hold 15–30 seconds."}, {"sv": "Återgå långsamt till neutralt läge.", "en": "Return to neutral slowly."}, {"sv": "Upprepa åt vänster i 15-30 sekunder. Gör 2-3 omgångar per sida, rör dig mjukt och utan smärta.", "en": "Repeat to the left side for 15–30 seconds; perform 2–3 rounds per side, moving gently and without pain."}]$instr$::jsonb WHERE name = 'Nackstretch åt sidan (kroppsvikt)' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Stå framför en låda eller plattform med fötterna axelbrett isär.", "en": "Stand in front of a box or platform with your feet shoulder-width apart."}, {"sv": "Böj knäna och hoppa upp på lådan. Landa mjukt med ena foten på lådan och den andra foten utanför kanten.", "en": "Bend your knees and jump onto the box, landing softly with one foot on the box and the other foot hanging off the edge."}, {"sv": "Stabilisera dig på lådan med foten som står på den, medan den andra foten hålls i luften.", "en": "Stabilize yourself on the box with the foot that is on it, while keeping the other foot off the ground."}, {"sv": "Håll positionen några sekunder och aktivera vadmusklerna för att hålla balansen.", "en": "Hold this position for a few seconds, engaging your calf muscles to maintain balance."}, {"sv": "Kliv långsamt ner med foten som står på lådan och återgå till startpositionen.", "en": "Slowly step down with the foot that is on the box, returning to the starting position."}, {"sv": "Upprepa övningen med andra benet.", "en": "Repeat the exercise with the other leg."}]$instr$::jsonb WHERE name = 'Nedhopp från låda med enbensstabilisering' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Ställ in sitthöjden och ryggstödet på maskinen i en bekväm position.", "en": "Adjust the seat height and backrest of the leverage machine to a comfortable position."}, {"sv": "Sitt i maskinen med ryggen mot ryggstödet och fötterna platt i golvet.", "en": "Sit on the machine with your back against the backrest and your feet flat on the floor."}, {"sv": "Greppa handtagen med överhandsgrepp och placera händerna något bredare än axelbrett.", "en": "Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart."}, {"sv": "Tryck handtagen framåt och bort från kroppen tills armarna är helt sträckta.", "en": "Push the handles forward and away from your body until your arms are fully extended."}, {"sv": "Sänk långsamt handtagen tillbaka mot bröstet med armbågarna lätt böjda.", "en": "Slowly lower the handles back towards your chest, keeping your elbows slightly bent."}, {"sv": "Pausa ett ögonblick i botten och tryck sedan tillbaka handtagen till startpositionen.", "en": "Pause for a moment at the bottom, then push the handles back to the starting position."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Negativ bröstpress i maskin' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Ställ in den negativa bänken i önskad vinkel.", "en": "Adjust the decline bench to the desired angle."}, {"sv": "Lägg dig på bänken med fötterna säkrade under fotdynorna.", "en": "Lie down on the bench with your feet secured under the foot pads."}, {"sv": "Greppa stången med ett brett grepp, något bredare än axelbrett.", "en": "Grasp the barbell with a wide grip, slightly wider than shoulder-width apart."}, {"sv": "Lyft ur stången och sänk den långsamt mot bröstet med armbågarna riktade utåt.", "en": "Unrack the barbell and lower it slowly towards your chest, keeping your elbows pointed outwards."}, {"sv": "Pausa ett ögonblick när stången nuddar bröstet.", "en": "Pause for a moment when the barbell touches your chest."}, {"sv": "Pressa tillbaka stången till startpositionen med helt utsträckta armar.", "en": "Push the barbell back up to the starting position, fully extending your arms."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Negativ bänkpress brett grepp i smithmaskin' AND user_id IS NULL;
