UPDATE exercises SET instructions = $instr$[{"sv": "Välj en medeltung kettlebell, håll den i hornen i brösthöjd och pressa den sedan över huvudet tills armbågarna är raka och handlederna neutrala.", "en": "Select a moderate kettlebell, hold it by the horns at chest height, then press it overhead until elbows are straight and wrists neutral."}, {"sv": "Hitta din position: revbenen ner, bäckenet neutralt, mage och säte spända, överarmarna i linje med eller strax bakom öronen.", "en": "Set your position: ribs down, pelvis neutral, abs and glutes braced; biceps align with or slightly behind the ears."}, {"sv": "Sträck aktivt kettlebellen mot taket så att skulderbladen roterar uppåt, håll vikten staplad över mitten av foten.", "en": "Actively reach the kettlebell to the ceiling so the shoulder blades upwardly rotate; keep the weight stacked over the midfoot."}, {"sv": "Börja gå med små, kontrollerade steg och rak hållning, utan att luta dig, fälla ut revbenen eller svanka.", "en": "Begin walking with small, controlled steps and a tall posture—no leaning, rib flare, or low‑back arch."}, {"sv": "Håll kettlebellen stabil så att den inte driver framåt eller bakåt, blicken framåt, och andas bakom bålspänningen.", "en": "Keep the kettlebell stable (no drifting forward/back), eyes forward, and breathe behind the brace."}, {"sv": "Vänd försiktigt vid behov utan att tappa låsningen över huvudet eller bålens position.", "en": "Turn carefully as needed without losing overhead lockout or trunk alignment."}, {"sv": "Efter setet stannar du, sänker kettlebellen kontrollerat till bröstet och sedan till golvet.", "en": "After the set, stop, lower the kettlebell to the chest with control, then to the floor."}]$instr$::jsonb WHERE name = 'Overhead carry med kettlebell' AND user_id IS NULL;
