UPDATE exercises SET instructions = $instr$[{"sv": "Ställ in en lutande bänk i 45 graders vinkel och fäst ett kabelhandtag i det nedre blocket.", "en": "Set up an incline bench at a 45-degree angle and attach a cable handle to the low pulley."}, {"sv": "Sitt på bänken vänd mot kabelmaskinen med fötterna i golvet och knäna lätt böjda.", "en": "Sit on the bench facing the cable machine with your feet flat on the floor and your knees slightly bent."}, {"sv": "Greppa kabelhandtaget med överhandsgrepp och sträck ut armarna helt framför dig.", "en": "Grasp the cable handle with an overhand grip and extend your arms fully in front of you."}, {"sv": "Luta dig framåt från höfterna med rak rygg och spänd bål.", "en": "Lean forward from your hips while keeping your back straight and your core engaged."}, {"sv": "Dra kabelhandtaget mot bröstet genom att dra ihop skulderbladen och böja armbågarna.", "en": "Pull the cable handle towards your chest by retracting your shoulder blades and bending your elbows."}, {"sv": "Krama åt ryggmusklerna i rörelsens topp och sträck sedan långsamt tillbaka armarna till startpositionen.", "en": "Squeeze your back muscles at the top of the movement, then slowly extend your arms back to the starting position."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Rodd på lutande bänk i kabel' AND user_id IS NULL;
