UPDATE exercises SET instructions = $instr$[{"sv": "Justera sitsens höjd och sätt dig i maskinen med fötterna platt i golvet.", "en": "Adjust the seat height and position yourself on the machine with your feet flat on the floor."}, {"sv": "Greppa handtagen med ett pronerat grepp, något smalare än axelbrett.", "en": "Grasp the handles with an overhand grip, slightly narrower than shoulder-width apart."}, {"sv": "Håll ryggen rak och bröstet lyft när du drar handtagen mot kroppen och pressar ihop skulderbladen.", "en": "Keep your back straight and your chest up as you pull the handles towards your body, squeezing your shoulder blades together."}, {"sv": "Pausa ett ögonblick i rörelsens slutläge och för sedan långsamt tillbaka handtagen till startpositionen.", "en": "Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Rodd smalt grepp i smithmaskin' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Ligg på rygg med benen raka och ihop och armarna ovanför huvudet. Spänn bålen och pressa ländryggen lätt mot golvet.", "en": "Lie on your back with legs straight together and arms overhead; brace your core and press your lower back gently into the floor."}, {"sv": "Lyft benen till 90 grader, tippa bäckenet bakåt och rulla upp ryggraden kota för kota från golvet så att benen förs över huvudet. Håll vikten på övre ryggen och axlarna och låt nacken vara avslappnad.", "en": "Lift legs to 90°, posteriorly tilt the pelvis, and articulate the spine off the floor to roll the legs overhead, keeping weight on upper back/shoulders and the neck relaxed."}, {"sv": "Stanna där du kan kontrollera positionen utan tryck på nacken, med benen långa och ihop.", "en": "Stop where you can control the position without cervical pressure, legs long and together."}, {"sv": "Svep armarna framåt och påbörja en kontrollerad rullning tillbaka, sänk ryggraden kota för kota medan du vecklar ut benen.", "en": "Sweep the arms forward and begin a controlled reverse roll, segmenting the spine back down as you unfold the legs."}, {"sv": "Fäll i höfterna för att sätta dig upp och balansera på sittbensknölarna i en V-sittande position, med överkropp och ben i ungefär 45 till 60 grader, armarna sträckta mot tårna och bröstet lyft.", "en": "Hinge at the hips to sit up and balance on your sit bones in a V-sit, torso and legs about 45–60 degrees, arms reaching toward toes, chest lifted."}, {"sv": "Pausa kort med magen spänd, tippa sedan bäckenet och runda ryggen för att rulla tillbaka med kontroll.", "en": "Pause briefly with abs braced, then tuck the pelvis and round the spine to roll back with control."}, {"sv": "Andas ut när du reser dig upp i V-sittet, andas in när du rullar tillbaka. Rör dig mjukt och låt inte hälarna slå i golvet.", "en": "Exhale as you rise to the V-sit; inhale as you roll back. Move smoothly and do not let the heels slam to the floor."}]$instr$::jsonb WHERE name = 'Rollover till V-sit' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Stå i kampställning med fötterna axelbrett isär och händerna uppe.", "en": "Stand in a fighting stance with feet shoulder-width and hands up."}, {"sv": "Flytta vikten till främre benet och pivotera på trampdynan, vrid höfter och huvud för att se målet över axeln.", "en": "Shift weight to the lead leg and pivot on its ball, turning your hips and head to spot the target over your shoulder."}, {"sv": "Ladda bakre benet genom att föra knät tvärs över och hälen mot sätet, med tårna pekande nedåt.", "en": "Chamber the rear leg by bringing the knee across and heel toward the glute, toes pointing down."}, {"sv": "Sträck ut höft och knä och driv hälen rakt bakåt i en rak bana, träffa med hälen.", "en": "Extend the hip and knee to drive the heel straight back along a linear path, striking with the heel."}, {"sv": "Håll bålen spänd och överkroppen lätt framåtlutad, behåll balansen på stödbenet.", "en": "Keep the core braced and torso slightly inclined forward; maintain balance on the supporting foot."}, {"sv": "Dra tillbaka benet direkt efter träffen, sätt sedan ner det och återgå till din ställning.", "en": "Re-chamber the leg immediately after contact, then set it down and return to your stance."}]$instr$::jsonb WHERE name = 'Roterande bakåtspark' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Börja i kampställning med fötterna axelbrett isär, mjuka knän och händerna uppe.", "en": "Start in a fighting stance with feet shoulder-width apart, knees soft, and hands up."}, {"sv": "Pivotera på främre foten och vrid huvud och axlar först för att se målet och starta rotationen.", "en": "Pivot on the lead foot and turn your head and shoulders first to spot the target, initiating the spin."}, {"sv": "Rotera höfter och överkropp, håll stödbenets häl vriden utåt för att skydda knät.", "en": "Rotate hips and torso, keeping the support heel turned outward to protect the knee."}, {"sv": "Ladda sparkbenet genom att lyfta knät åt sidan (abduktion) med lätt böjt knä.", "en": "Chamber the kicking leg by lifting the knee to the side (abduction) with the knee slightly bent."}, {"sv": "Sträck ut benet och svep hälen i en krokformad bana, träffa med baksidan av hälen på målets höjd.", "en": "Extend the leg and sweep the heel across in a hooking path, striking with the back of the heel at the target height."}, {"sv": "Håll bålen spänd och överkroppen upprätt, översträck inte knät vid träffen.", "en": "Keep the core braced and torso upright; do not hyperextend the knee on contact."}, {"sv": "Dra tillbaka benet efter sparken och sätt ner det kontrollerat, återgå till ställningen.", "en": "Re-chamber the leg after the strike and place it down under control, returning to stance."}, {"sv": "Återfå balansen och upprepa sedan på samma eller motsatt sida.", "en": "Reset balance, then repeat on the same or opposite side."}]$instr$::jsonb WHERE name = 'Roterande krokspark' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Ställ in sitshöjden så att knäna är lätt böjda och fötterna vilar plant mot fotplattan.", "en": "Adjust the seat height so that your knees are slightly bent and your feet are flat on the footplate."}, {"sv": "Placera tårna på fotplattan med hälarna hängande utanför kanten.", "en": "Place your toes on the footplate, with your heels hanging off the edge."}, {"sv": "Greppa handtagen eller maskinens sidor för stabilitet.", "en": "Grasp the handles or the sides of the machine for stability."}, {"sv": "Pressa genom framfoten och lyft hälarna så högt som möjligt.", "en": "Push through the balls of your feet, raising your heels as high as possible."}, {"sv": "Pausa ett ögonblick i toppen och sänk sedan långsamt hälarna tillbaka till startpositionen.", "en": "Pause for a moment at the top, then slowly lower your heels back down to the starting position."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Roterande vadpress i maskin' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Stå i kampställning med fötterna axelbrett, bakre hälen lätt lyft och händerna uppe i gard.", "en": "Stand in fighting stance with feet shoulder-width, rear heel slightly raised and hands up to guard."}, {"sv": "Flytta vikten till stödbenet, pivotera på den foten så att hälen vrids utåt och höfterna öppnas.", "en": "Shift weight to the support leg, pivot that foot so the heel turns outward and the hips open."}, {"sv": "Ladda sparkbenet genom att lyfta knät över kroppen med smalbenet parallellt med golvet.", "en": "Chamber the kicking leg by lifting the knee across the body with the shin parallel to the floor."}, {"sv": "Snärta till sparken genom att snabbt sträcka knät och träffa med smalbenet eller vristen. Andas ut vid träffen.", "en": "Snap the kick by rapidly extending the knee, striking with the shin or instep; exhale on impact."}, {"sv": "Håll överkroppen upprätt, bålen spänd och blicken på målet under hela rörelsen.", "en": "Keep the torso upright, core tight, and eyes on target throughout."}, {"sv": "Dra omedelbart tillbaka benet till laddat läge, sätt sedan ner det kontrollerat och återgå till ställningen.", "en": "Re-chamber the leg immediately, then place it down under control and return to stance."}, {"sv": "Upprepa önskat antal repetitioner, byt sedan sida.", "en": "Repeat for reps, then switch sides."}]$instr$::jsonb WHERE name = 'Roundhouse kick' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Stå med fötterna axelbrett isär och håll en hantel i varje hand med överhandsgrepp.", "en": "Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip."}, {"sv": "Håll ryggen rak och bålen spänd, fäll i höften och sänk hantlarna mot golvet medan knäna böjs lätt.", "en": "Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing your knees to bend slightly."}, {"sv": "Sänk hantlarna tills du känner en sträckning i baksida lår, tryck sedan genom hälarna och spänn sätesmusklerna för att återgå till startpositionen.", "en": "Lower the dumbbells until you feel a stretch in your hamstrings, then push through your heels and engage your glutes to return to the starting position."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Rumänska marklyft med hantlar' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Sitt på golvet med böjda knän och fötterna platt i golvet.", "en": "Sit on the ground with your knees bent and your feet flat on the floor."}, {"sv": "Håll en vikt eller medicinboll med båda händerna framför bröstet.", "en": "Hold a weight or medicine ball with both hands in front of your chest."}, {"sv": "Luta dig lätt bakåt med rak rygg och spänd bål.", "en": "Lean back slightly, keeping your back straight and your core engaged."}, {"sv": "Vrid långsamt överkroppen åt höger och för vikten eller medicinbollen mot golvet på din högra sida.", "en": "Slowly twist your torso to the right, bringing the weight or medicine ball towards the floor on your right side."}, {"sv": "Pausa ett ögonblick och vrid sedan överkroppen åt vänster och för vikten eller medicinbollen mot golvet på din vänstra sida.", "en": "Pause for a moment, then twist your torso to the left, bringing the weight or medicine ball towards the floor on your left side."}, {"sv": "Fortsätt växla sida önskat antal repetitioner.", "en": "Continue alternating sides for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Russian twist med vikt' AND user_id IS NULL;
