UPDATE exercises SET instructions = $instr$[{"sv": "Stå med fötterna axelbrett isär och skivstången på golvet framför dig.", "en": "Stand with your feet shoulder-width apart and the barbell on the ground in front of you."}, {"sv": "Böj knäna och fäll i höften ner i en knäböjsposition, och greppa stången med ett pronerat grepp.", "en": "Bend your knees and hinge at the hips to lower into a squat position, gripping the barbell with an overhand grip."}, {"sv": "Håll ryggen rak och bröstet lyft när du trycker genom hälarna för att lyfta stången från golvet och sträcker ut höfter och knän.", "en": "Keep your back straight and chest up as you drive through your heels to lift the barbell off the ground, extending your hips and knees."}, {"sv": "När stången når höfthöjd, dra den explosivt uppåt, rulla upp axlarna och dra armbågarna högt och ut åt sidorna.", "en": "As the barbell reaches hip level, explosively pull it upwards, shrugging your shoulders and pulling your elbows high and to the sides."}, {"sv": "När stången når sin högsta punkt, gå snabbt ner under den och dra dig ner i en djup knäböjsposition.", "en": "As the barbell reaches its highest point, quickly drop underneath it, pulling yourself into a deep squat position."}, {"sv": "Fånga stången ovanför huvudet med helt utsträckta armar och böjda knän.", "en": "Catch the barbell overhead with your arms fully extended and your knees bent."}, {"sv": "Res dig upp genom att sträcka på höfter och knän med stången kvar ovanför huvudet.", "en": "Stand up by extending your hips and knees, keeping the barbell overhead."}, {"sv": "Sänk stången tillbaka till startpositionen genom att göra rörelsen i omvänd ordning.", "en": "Lower the barbell back down to the starting position by reversing the movement."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Ryckdrag' AND user_id IS NULL;
