UPDATE exercises SET instructions = $instr$[{"sv": "Stå i atletisk position: fötterna höftbrett isär, knäna mjukt böjda, bröstet uppe och blicken framåt.", "en": "Stand athletic: feet hip-width, knees softly bent, chest up, eyes forward."}, {"sv": "Ladda i höfter och fotleder och hoppa diagonalt över linjen till motsatt sida av nästa kon, landa på framfoten.", "en": "Load through the hips and ankles and hop diagonally over the line to the opposite side of the next cone, landing on the balls of your feet."}, {"sv": "Dämpa landningen mjukt genom att böja fotleder, knän och höfter och håll knäna i linje över tårna.", "en": "Absorb the landing softly by bending the ankles, knees, and hips while keeping knees tracking over toes."}, {"sv": "Studsa direkt vidare in i nästa diagonala hopp och använd armpendling för balans och rytm.", "en": "Immediately rebound into the next diagonal hop, using arm swing for balance and rhythm."}, {"sv": "Håll överkroppen neutral och gör hoppen låga till måttliga och snabba för att betona kontroll och reaktivitet.", "en": "Maintain a neutral torso and keep hops low-to-moderate and quick to emphasize control and reactivity."}, {"sv": "Fortsätt hoppa förbi alla koner, gå sedan tillbaka för att återhämta dig och upprepa önskat antal reps eller önskad tid.", "en": "Continue hopping past all cones, then walk back to recover and repeat for the desired reps or time."}, {"sv": "Om tekniken försämras, sänk tempot eller minska hoppens längd eller höjd.", "en": "If form degrades, slow the pace or reduce hop distance/height."}]$instr$::jsonb WHERE name = 'Sicksackhopp' AND user_id IS NULL;
