UPDATE exercises SET instructions = $instr$[{"sv": "Stå upprätt i kampställning, fötterna höftbrett, händerna uppe och bålen spänd.", "en": "Stand tall in a fighting stance, feet hip-width, hands up, core braced."}, {"sv": "Flytta vikten till stödbenet, böj det lätt och pivotera på stödfoten så att tårna vrids bort från sparksidan.", "en": "Shift weight to the supporting leg, bend it slightly, and pivot the supporting foot so toes turn away from the kicking side."}, {"sv": "Lyft det motsatta knät mot bröstet i laddat läge, med hälen indragen, tårna uppdragna och höfterna staplade.", "en": "Lift the opposite knee toward the chest (chamber), heel tucked, toes pulled back, hips stacked."}, {"sv": "Sträck benet ut åt sidan och driv hälen mot målet i ungefär höfthöjd. Håll knät mjukt, lås inte ut det.", "en": "Extend the leg out to the side, driving the heel toward the target at about hip height; keep the knee soft—do not lock out."}, {"sv": "Håll överkroppen upprätt och bäckenet i våg, behåll en neutral ryggrad genom hela rörelsen.", "en": "Keep torso upright and pelvis level; maintain a neutral spine throughout."}, {"sv": "Håll kort, dra sedan tillbaka knät längs samma bana.", "en": "Briefly hold, then re-chamber the knee along the same path."}, {"sv": "Sänk foten kontrollerat till golvet och upprepa, byt sida jämnt.", "en": "Lower the foot to the floor under control and repeat; switch sides evenly."}]$instr$::jsonb WHERE name = 'Sidospark' AND user_id IS NULL;
