UPDATE exercises SET instructions = $instr$[{"sv": "Ställ in en låg trissa och fäst huvudselens ring i karbinhaken.", "en": "Set a low pulley and clip the head harness ring to the carabiner."}, {"sv": "Sitt vänd mot viktmagasinet med fötterna plant i golvet och överkroppen upprätt, flytta dig bakåt tills kabeln är spänd.", "en": "Sit facing the stack with feet flat and torso upright; slide back until the cable is taut."}, {"sv": "Ta på dig selen med dynan centrerad över pannan och remmen åtsittande.", "en": "Put on the harness with the pad centered on your forehead and the strap snug."}, {"sv": "Börja med hakan lätt indragen och nacken lätt böjd framåt, håll axlarna nere och bålen spänd.", "en": "Start with a slight chin tuck and mild neck flexion; keep shoulders down and core braced."}, {"sv": "Andas ut och sträck nacken bakåt tills huvudet når neutralläge eller en lätt bakåtböjning, svanka inte med ländryggen.", "en": "Exhale and extend your neck back until your head reaches neutral or a slight extension—do not arch the lower back."}, {"sv": "Pausa kort, andas sedan in och återgå långsamt och kontrollerat till startpositionen.", "en": "Pause briefly, then inhale and slowly return to the starting position under control."}, {"sv": "Håll ett jämnt tempo, undvik ryck och håll rörelsen inom ett smärtfritt omfång, överdriv inte bakåtböjningen.", "en": "Maintain a smooth tempo, avoid jerking, and keep the range pain‑free; do not hyperextend."}, {"sv": "Öka belastningen i små steg och avbryt om du känner obehag i nackens leder eller stickningar.", "en": "Use small load increases and stop if you feel neck joint discomfort or tingling."}]$instr$::jsonb WHERE name = 'Sittande nackextension med huvudsele' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Sitt nära kanten av en bänk med fötterna platt i golvet och överkroppen lätt framåtlutad. Vila underarmarna mot låren för stöd.", "en": "Sit near the edge of a bench with feet flat and torso slightly leaned forward; rest forearms on thighs to brace."}, {"sv": "Sätt fast huvudselen så att den sitter tätt och rakt. Fäst en liten viktskiva i den främre ringen.", "en": "Secure the head harness so it sits snug and level; attach a small weight plate to the front ring."}, {"sv": "Börja med hakan lätt indragen och nacken böjd så att viktskivan hänger lodrätt under huvudet.", "en": "Start with your chin gently tucked and neck flexed so the plate hangs vertically below your head."}, {"sv": "Håll överkroppen stilla och sträck nacken genom att lyfta huvudet tills det är i linje med överkroppen. Undvik att översträcka.", "en": "Keeping your torso still, extend your neck by lifting your head until it aligns with your torso—avoid hyperextension."}, {"sv": "Pausa kort i toppläget och sänk sedan huvudet långsamt till startpositionen genom ett bekvämt och smärtfritt rörelseomfång.", "en": "Pause briefly at the top, then lower your head slowly to the starting position through a comfortable, pain‑free range."}, {"sv": "Andas ut när du sträcker och in när du sänker. Rör dig jämnt utan ryck och avbryt om du känner smärta i nacken.", "en": "Breathe out as you extend and in as you lower; move steadily without jerking and stop if you feel neck pain."}]$instr$::jsonb WHERE name = 'Sittande nackextension med huvudsele (viktad)' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Ställ in trissan ungefär i huvudhöjd när du sitter och välj en mycket lätt vikt.", "en": "Set a cable pulley roughly at seated head height and select a very light weight."}, {"sv": "Sätt dig på en bänk med ryggen mot maskinen och fäst huvudselens D-ring bakom huvudet i kabeln.", "en": "Sit on a bench facing away from the machine; clip the head harness D‑ring behind your head to the cable."}, {"sv": "Sitt upprätt med fötterna plant i golvet, bålen spänd, axlarna avslappnade och nacken i neutralt läge.", "en": "Sit tall with feet flat, core braced, shoulders relaxed, and neck in neutral alignment."}, {"sv": "Förspänn kabeln genom att flytta dig något framåt utan att böja nacken bakåt.", "en": "Pre-tension the cable by scooting forward slightly without extending the neck."}, {"sv": "Andas ut och böj nacken framåt genom att nicka hakan mot bröstet inom ett bekvämt omfång utan att runda överkroppen.", "en": "Exhale and flex the neck, nodding the chin toward the chest through a comfortable range without rounding the torso."}, {"sv": "Pausa kort och återgå sedan långsamt till neutralläge medan du håller emot draget, böj inte nacken för långt bakåt.", "en": "Pause briefly, then slowly return to neutral while resisting the pull—do not hyperextend."}, {"sv": "Håll rörelsen mjuk och liten, avbryt direkt om du känner smärta eller yrsel.", "en": "Keep the motion smooth and small; stop immediately if you feel pain or dizziness."}]$instr$::jsonb WHERE name = 'Sittande nackflexion med huvudsele' AND user_id IS NULL;
