UPDATE exercises SET instructions = $instr$[{"sv": "Stå med fötterna axelbrett isär och håll en skivstång framför låren med överhandsgrepp.", "en": "Stand with your feet shoulder-width apart and hold a barbell in front of your thighs with an overhand grip."}, {"sv": "Böj knäna lätt och fäll fram från höfterna med rak rygg och bröstet uppe.", "en": "Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up."}, {"sv": "Lyft skivstången upp mot axlarna samtidigt som du hoppar lätt från golvet.", "en": "Simultaneously lift the barbell up towards your shoulders while jumping slightly off the ground."}, {"sv": "När du når rörelsens topp vänder du snabbt rörelsen och sänker skivstången tillbaka ner till startpositionen.", "en": "As you reach the top of the movement, quickly reverse the motion and lower the barbell back down to the starting position."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Skidåkarsving med skivstång' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Börja med att hänga i en stång med armarna helt sträckta och kroppen avslappnad.", "en": "Start by hanging from a bar with your arms fully extended and your body relaxed."}, {"sv": "Spänn bålen och lyft benen, för knäna mot bröstet.", "en": "Engage your core and lift your legs up, bringing your knees towards your chest."}, {"sv": "Fortsätt lyfta benen upp och över huvudet så att kroppen passerar genom armarna.", "en": "Continue to lift your legs up and over your head, allowing your body to pass through the arms."}, {"sv": "När benen är helt utsträckta över huvudet, börja sänka dem tillbaka mot startpositionen.", "en": "Once your legs are fully extended over your head, begin to lower them back down towards the starting position."}, {"sv": "Medan du sänker benen, låt kroppen passera tillbaka genom armarna tills du hänger med armarna helt sträckta igen.", "en": "As you lower your legs, allow your body to pass back through the arms until you are hanging with your arms fully extended again."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Skin the cat' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Stå upprätt med fötterna axelbrett isär och håll en skivstång med underhandsgrepp, handflatorna framåt.", "en": "Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing forward."}, {"sv": "Håll armbågarna nära kroppen och andas ut medan du curlar vikten och spänner biceps.", "en": "Keep your elbows close to your torso and exhale as you curl the weights while contracting your biceps."}, {"sv": "Fortsätt lyfta stången tills biceps är helt kontraherade och stången är i axelhöjd.", "en": "Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level."}, {"sv": "Håll den kontraherade positionen en kort paus medan du kniper åt biceps.", "en": "Hold the contracted position for a brief pause as you squeeze your biceps."}, {"sv": "Andas in medan du långsamt börjar sänka stången tillbaka till startpositionen.", "en": "Inhale as you slowly begin to lower the bar back to the starting position."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Skivstångscurl' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Ställ in en lutande bänk i 45 graders vinkel.", "en": "Set up an incline bench at a 45-degree angle."}, {"sv": "Ligg framstupa på bänken med bröstet mot dynan och fötterna i golvet.", "en": "Lie face down on the bench with your chest against the pad and your feet flat on the ground."}, {"sv": "Greppa skivstången med överhandsgrepp, något bredare än axelbrett.", "en": "Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart."}, {"sv": "Håll ryggen rak och bålen spänd.", "en": "Keep your back straight and your core engaged."}, {"sv": "Dra skivstången mot bröstet och pressa ihop skulderbladen.", "en": "Pull the barbell towards your chest, squeezing your shoulder blades together."}, {"sv": "Pausa ett ögonblick i toppläget och sänk sedan långsamt tillbaka skivstången till startpositionen.", "en": "Pause for a moment at the top, then slowly lower the barbell back to the starting position."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Skivstångsrodd på lutande bänk' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Ligg plant på en bänk med fötterna i golvet och huvudet vid bänkens kortsida.", "en": "Lie flat on a bench with your feet flat on the ground and your head at the end of the bench."}, {"sv": "Håll skivstången med omvänt grepp, handflatorna vända mot ansiktet och händerna axelbrett isär.", "en": "Hold the barbell with a reverse grip, palms facing towards your face, and your hands shoulder-width apart."}, {"sv": "Sträck armarna rakt upp över bröstet med armbågarna inåt och handlederna raka.", "en": "Extend your arms straight up over your chest, keeping your elbows in and your wrists straight."}, {"sv": "Sänk långsamt skivstången mot pannan genom att böja armbågarna och hålla överarmarna stilla.", "en": "Slowly lower the barbell towards your forehead by bending your elbows, keeping your upper arms stationary."}, {"sv": "Pausa ett ögonblick i botten och sträck sedan armarna tillbaka upp till startpositionen.", "en": "Pause for a moment at the bottom, then extend your arms back up to the starting position."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Skull crusher omvänt grepp' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Sitt på en plan bänk med en hantel i varje hand vilande på låren.", "en": "Sit on a flat bench with a dumbbell in each hand, resting on your thighs."}, {"sv": "Använd låren för att hjälpa till att lyfta hantlarna, en i taget, så att du kan hålla dem framför dig i axelbredd.", "en": "Using your thighs to help raise the dumbbells, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width."}, {"sv": "Väl i axelbredd, rotera handlederna framåt så att handflatorna pekar bort från dig. Detta är din startposition.", "en": "Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position."}, {"sv": "Andas in och sänk långsamt hantlarna mot sidorna tills de är ungefär i höjd med bröstet.", "en": "As you breathe in, slowly lower the dumbbells to your side until they are about level with your chest."}, {"sv": "Andas ut och använd triceps för att lyfta hantlarna tillbaka till startpositionen.", "en": "As you exhale, use your triceps to lift the dumbbells back to the starting position."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Smal hantelpress' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Stå i kampställning med en fot fram, händerna uppe och bålen spänd.", "en": "Stand in a fighting stance with one foot forward, hands up, and core braced."}, {"sv": "Flytta vikten till stödbenet, behåll en lätt böj i det knät och håll höfterna riktade rakt fram.", "en": "Shift weight to the support leg, keeping a slight bend in that knee and hips square."}, {"sv": "Ladda sparken: lyft knät på sparkbenet till ungefär höfthöjd, sträck vristen och dra tårna bakåt så att trampdynan exponeras.", "en": "Chamber the kick: lift the knee of the kicking leg to about hip height; plantarflex the ankle and pull the toes back to expose the ball of the foot."}, {"sv": "Snärta sparken framåt genom att snabbt sträcka knät och träffa ett lågt till medelhögt mål, andas ut och håll överkroppen upprätt.", "en": "Snap the kick forward by rapidly extending the knee, striking a low–to–mid target; exhale and keep the torso tall."}, {"sv": "Ladda om direkt genom att böja knät och föra hälen tillbaka under höften (lås inte sparkbenets knä).", "en": "Re-chamber immediately by bending the knee and bringing the heel back under the hip (do not lock the kicking knee)."}, {"sv": "Sätt ner foten kontrollerat i din ställning och upprepa önskat antal repetitioner, byt sedan sida.", "en": "Set the foot down under control into your stance and repeat for reps, then switch sides."}]$instr$::jsonb WHERE name = 'Snap kick framåt' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Ligg på rygg med böjda knän och fötterna i golvet.", "en": "Lie on your back with your knees bent and feet flat on the floor."}, {"sv": "Placera händerna bakom huvudet eller korsa dem över bröstet.", "en": "Place your hands behind your head or cross them over your chest."}, {"sv": "Spänn magen och lyft skulderbladen från golvet samtidigt som du roterar överkroppen åt ena sidan.", "en": "Engage your abs and lift your shoulder blades off the floor, rotating your torso to one side."}, {"sv": "Pausa ett ögonblick och sänk sedan skulderbladen tillbaka till golvet.", "en": "Pause for a moment, then lower your shoulder blades back down to the floor."}, {"sv": "Upprepa på andra sidan och växla sida vid varje repetition.", "en": "Repeat on the other side, alternating sides with each repetition."}]$instr$::jsonb WHERE name = 'Sneda crunches på golv' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Stå med fötterna axelbrett isär och tårna lätt utåtvridna.", "en": "Stand with your feet shoulder-width apart, toes slightly turned out."}, {"sv": "Håll skivstången över övre delen av ryggen, vilande på kappmuskeln eller bakre axlarna.", "en": "Hold the barbell across your upper back, resting it on your traps or rear delts."}, {"sv": "Spänn bålen och håll bröstet uppe medan du sänker höfterna bakåt och nedåt, som om du sätter dig på en stol.", "en": "Engage your core and keep your chest up as you lower your hips back and down, as if sitting into a chair."}, {"sv": "Sänk dig tills låren är parallella med golvet, eller så lågt du bekvämt kan komma.", "en": "Lower until your thighs are parallel to the ground, or as low as you can comfortably go."}, {"sv": "Tryck ifrån med hälarna för att resa dig upp igen och knip åt i sätet i toppen.", "en": "Drive through your heels to stand back up, squeezing your glutes at the top."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Speed squat med skivstång' AND user_id IS NULL;
