UPDATE exercises SET instructions = $instr$[{"sv": "Börja i armhävningsposition med händerna något bredare än axelbrett och fötterna ihop.", "en": "Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together."}, {"sv": "För höger knä mot höger armbåge utan att låta det nudda golvet.", "en": "Bring your right knee towards your right elbow, keeping it off the ground."}, {"sv": "Samtidigt som du för tillbaka höger knä sänker du kroppen mot golvet genom att böja armbågarna.", "en": "As you bring your right knee back, simultaneously lower your body towards the ground by bending your elbows."}, {"sv": "Pressa upp till startpositionen igen och upprepa med vänster knä mot vänster armbåge.", "en": "Push back up to the starting position and repeat with your left knee towards your left elbow."}, {"sv": "Fortsätt växla sida önskat antal repetitioner.", "en": "Continue alternating sides for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Spider crawl armhävning' AND user_id IS NULL;
