UPDATE exercises SET instructions = $instr$[{"sv": "Ställ in en lutande bänk i 45 graders vinkel.", "en": "Set up an incline bench at a 45-degree angle."}, {"sv": "Ligg på mage på bänken med bröst och mage vilande mot den.", "en": "Lie face down on the bench with your chest and stomach resting against it."}, {"sv": "Håll en skivstång med underhandsgrepp, axelbrett isär.", "en": "Hold a barbell with an underhand grip, shoulder-width apart."}, {"sv": "Sträck ut armarna helt och låt skivstången hänga ner mot golvet.", "en": "Extend your arms fully, allowing the barbell to hang down towards the floor."}, {"sv": "Håll överarmarna stilla, andas ut och curla vikten samtidigt som du spänner biceps.", "en": "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps."}, {"sv": "Fortsätt lyfta skivstången tills biceps är fullt kontraherad och stången är i axelhöjd.", "en": "Continue to raise the barbell until your biceps are fully contracted and the bar is at shoulder level."}, {"sv": "Håll den kontraherade positionen en kort stund medan du kniper åt i biceps.", "en": "Hold the contracted position for a brief pause as you squeeze your biceps."}, {"sv": "Andas in och börja långsamt sänka skivstången tillbaka till startpositionen.", "en": "Inhale and slowly begin to lower the barbell back to the starting position."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Spider curl med skivstång' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Stå upprätt och håll en skivstång med överhandsgrepp strax utanför låren, med fötterna höftbrett isär.", "en": "Stand tall holding a barbell with an overhand grip just outside your thighs; feet hip-width apart."}, {"sv": "Ta ett långt steg framåt till en splitposition (främre foten platt i golvet, bakre hälen lyft, tårna pekar framåt).", "en": "Step one foot forward into a long split stance (front foot flat, back heel lifted, toes pointing forward)."}, {"sv": "Spänn magen, håll bröstet uppe, höfterna rakt framåt och stången nära låren.", "en": "Brace your abs, keep your chest up, hips square, and the bar close to your thighs."}, {"sv": "Sänk dig rakt ner genom att böja båda knäna. Håll överkroppen upprätt och låt främre knät följa linjen över mittentårna.", "en": "Lower straight down by bending both knees; keep the torso tall and the front knee tracking over the middle toes."}, {"sv": "Sänk dig tills främre låret är nästan parallellt med golvet och bakre knät svävar strax ovanför golvet. Håll vikten på främre fotens mellandel och häl.", "en": "Descend until the front thigh is near parallel and the back knee hovers just above the floor; keep weight through the front mid-foot/heel."}, {"sv": "Pressa genom främre foten och bakre fotens trampdyna för att komma tillbaka till stående utan att låsa knäna.", "en": "Press through the front foot and the ball of the back foot to return to standing without locking the knees."}, {"sv": "Håll stången vågrät och nära kroppen. Låt inte främre knät falla inåt eller hälen lyfta.", "en": "Keep the bar level and close to the body; avoid letting the front knee cave inward or the heel lift."}, {"sv": "Gör alla reps på ena sidan, byt sedan ben och upprepa.", "en": "Complete all reps on one side, then switch legs and repeat."}]$instr$::jsonb WHERE name = 'Split squat med skivstång (version 2)' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Stå med fötterna bredare än axelbrett isär och tårna pekande lätt utåt.", "en": "Stand with your feet wider than shoulder-width apart, toes pointing slightly outward."}, {"sv": "Håll en skivstång över övre delen av ryggen, vilande på kappmuskeln.", "en": "Hold a barbell across your upper back, resting it on your traps."}, {"sv": "Spänn bålen och håll bröstet uppe medan du sänker kroppen ner i en knäböjsposition genom att böja i knän och höfter.", "en": "Engage your core and keep your chest up as you lower your body down into a squat position, bending at the knees and hips."}, {"sv": "Pressa knäna utåt på vägen ner och håll vikten på hälarna.", "en": "As you lower, push your knees out to the sides and keep your weight on your heels."}, {"sv": "Sänk dig tills låren är parallella med golvet och tryck sedan ifrån med hälarna för att återgå till startpositionen.", "en": "Lower until your thighs are parallel to the ground, then push through your heels to return to the starting position."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Split squat åt sidan med skivstång' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Ställ in smithmaskinen med stången i höfthöjd.", "en": "Set up the smith machine with the barbell at hip height."}, {"sv": "Stå vänd bort från maskinen med fötterna axelbrett isär.", "en": "Stand facing away from the machine with your feet shoulder-width apart."}, {"sv": "Kliv bakåt med höger fot och placera den på stången, med fotens ovansida vilande på stången.", "en": "Step back with your right foot and place it on the barbell, resting the top of your foot on the bar."}, {"sv": "Böj vänster knä och sänk kroppen ner i en utfallsposition med rak rygg.", "en": "Bend your left knee and lower your body into a lunge position, keeping your back straight."}, {"sv": "Tryck genom vänster häl för att återgå till startpositionen.", "en": "Push through your left heel to return to the starting position."}, {"sv": "Upprepa på andra sidan genom att kliva bakåt med vänster fot.", "en": "Repeat on the other side, stepping back with your left foot."}, {"sv": "Fortsätt växla sida önskat antal repetitioner.", "en": "Continue alternating sides for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Sprintutfall i smithmaskin' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Börja med skivstången vilande på axlarna och fötterna axelbrett isär.", "en": "Start with the barbell resting on your shoulders, with your feet shoulder-width apart."}, {"sv": "Sänk dig ner i en knäböj, håll bröstet uppe och låt knäna följa tårnas riktning.", "en": "Lower your body into a squat position, keeping your chest up and your knees tracking over your toes."}, {"sv": "När du når botten av knäböjen, pressa explosivt genom benen och tryck skivstången över huvudet.", "en": "As you reach the bottom of the squat, explosively drive through your legs and push the barbell overhead."}, {"sv": "När skivstången når sin högsta punkt, sjunk snabbt ner i en splitposition med en fot fram och en fot bak.", "en": "As the barbell reaches its peak, quickly drop into a split position, with one foot forward and one foot back."}, {"sv": "Fånga skivstången över huvudet med helt sträckta armar och det bakre knäet lätt mot golvet.", "en": "Catch the barbell overhead with your arms fully extended and your back knee slightly touching the ground."}, {"sv": "Res dig upp från splitpositionen och för ihop fötterna igen.", "en": "Stand up from the split position, bringing your feet back together."}, {"sv": "Sänk skivstången tillbaka till axlarna och upprepa i önskat antal repetitioner.", "en": "Lower the barbell back to your shoulders and repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Squat jerk' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Börja stående med fötterna axelbrett isär och armarna sträckta över huvudet.", "en": "Start by standing with your feet shoulder-width apart and your arms extended overhead."}, {"sv": "Böj knäna lätt och spänn bålen.", "en": "Bend your knees slightly and engage your core."}, {"sv": "Sänk dig ner i en knäböj medan du håller armarna sträckta över huvudet.", "en": "Lower your body down into a squat position while keeping your arms extended overhead."}, {"sv": "Medan du går ner i knäböjen, pressa armarna nedåt mot golvet och aktivera triceps.", "en": "As you squat down, press your arms down towards the ground, engaging your triceps."}, {"sv": "Pausa ett ögonblick i botten av knäböjen, tryck sedan genom hälarna för att resa dig upp samtidigt som du lyfter armarna över huvudet igen.", "en": "Pause for a moment at the bottom of the squat, then push through your heels to stand back up while simultaneously raising your arms back overhead."}, {"sv": "Upprepa i önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Stalder press' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Stå med fötterna höftbrett isär och armarna längs sidorna.", "en": "Stand with your feet hip-width apart and your arms by your sides."}, {"sv": "Ta ett steg bakåt med höger fot och landa på framfoten.", "en": "Take a step back with your right foot, landing on the ball of your foot."}, {"sv": "Böj vänster knä och sänk kroppen till ett utfall.", "en": "Bend your left knee and lower your body into a lunge position."}, {"sv": "Samtidigt som du sänker dig i utfallet sträcker du armarna över huvudet.", "en": "As you lower into the lunge, simultaneously reach your arms overhead."}, {"sv": "Pausa ett ögonblick i botten av utfallet och återgå sedan till startpositionen genom att pressa genom vänster häl och föra höger fot framåt.", "en": "Pause for a moment at the bottom of the lunge, then return to the starting position by pushing through your left heel and bringing your right foot forward."}, {"sv": "Upprepa rörelsen på andra sidan, kliv bakåt med vänster fot och böj höger knä.", "en": "Repeat the movement on the other side, stepping back with your left foot and bending your right knee."}, {"sv": "Fortsätt växla sida i önskat antal repetitioner.", "en": "Continue alternating sides for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Steg bakåt med sträckning över huvudet' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Stå framför en step eller plattform med en hantel i varje hand och handflatorna vända mot kroppen.", "en": "Stand in front of a step or platform with a dumbbell in each hand, palms facing your body."}, {"sv": "Placera höger fot på steppen och se till att hela foten har kontakt med ytan.", "en": "Place your right foot on the step, ensuring your entire foot is in contact with the surface."}, {"sv": "Spänn bålen och tryck genom höger häl för att lyfta dig upp på steppen, samtidigt som du för vänster knä upp mot bröstet.", "en": "Engage your core and push through your right heel to lift your body up onto the step, bringing your left knee up towards your chest."}, {"sv": "I toppen av rörelsen gör du en bicepscurl genom att böja armbågarna och föra hantlarna mot axlarna.", "en": "At the top of the movement, perform a bicep curl by bending your elbows and bringing the dumbbells towards your shoulders."}, {"sv": "Sänk tillbaka hantlarna och sänk samtidigt vänster fot till golvet igen.", "en": "Lower the dumbbells back down and simultaneously lower your left foot back to the ground."}, {"sv": "Upprepa rörelsen på andra sidan genom att kliva upp med vänster fot och curla hantlarna.", "en": "Repeat the movement on the opposite side, stepping up with your left foot and curling the dumbbells."}, {"sv": "Fortsätt växla sida i önskat antal repetitioner.", "en": "Continue alternating sides for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Step up med enbensbalans och bicepscurl' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Placera två stadiga bänkar ungefär ett steg ifrån varandra. Håll hantlarna längs sidorna med bröstet upp och bålen spänd.", "en": "Place two sturdy benches about a stride apart; hold dumbbells at your sides, chest up, core braced."}, {"sv": "Sätt främre foten plant på den främre bänken och ovansidan av bakre foten på den bakre bänken. Håll höfterna raka framåt och blicken framåt.", "en": "Put your front foot flat on the front bench and the top of your rear foot on the rear bench; hips square, eyes forward."}, {"sv": "Andas in och sänk dig rakt ner genom att böja båda knäna. Låt främre knät följa linjen över de mellersta tårna och håll hälen i underlaget.", "en": "Inhale and descend straight down by bending both knees, keeping the front knee tracking over the middle toes and heel grounded."}, {"sv": "Sänk dig tills främre foten lätt nuddar golvet (eller tills främre låret är minst parallellt med golvet), med lång överkropp och neutral rygg.", "en": "Lower until the front foot lightly touches the floor (or front thigh is at least parallel), torso tall and neutral spine."}, {"sv": "Andas ut och tryck genom främre hälen och mellanfoten för att sträcka knä och höft, och återvänd till startpositionen uppe på bänkarna.", "en": "Exhale and drive through the front heel and mid‑foot to extend the knee and hip, returning to the start atop the benches."}, {"sv": "Minimera frånskjutet från bakre benet. Håll hantlarna stilla och axlarna sänkta.", "en": "Minimize push from the rear leg; keep dumbbells still and shoulders down."}, {"sv": "Pausa, hitta balansen igen och gör klart alla reps innan du byter ben.", "en": "Pause, re-balance, and complete all reps before switching legs."}]$instr$::jsonb WHERE name = 'Step up med utfall och hantlar' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Stå framför en bänk eller step med en hantel i varje hand och handflatorna vända mot kroppen.", "en": "Stand in front of a bench or step with a dumbbell in each hand, palms facing your body."}, {"sv": "Placera höger fot på bänken eller steppen och se till att hela foten har kontakt med ytan.", "en": "Place your right foot on the bench or step, ensuring your entire foot is in contact with the surface."}, {"sv": "Tryck genom höger häl och lyft dig upp på bänken eller steppen medan du sträcker höger ben.", "en": "Push through your right heel and lift your body up onto the bench or step, straightening your right leg."}, {"sv": "Ta upp vänster fot på bänken eller steppen så att du står helt upprätt.", "en": "Bring your left foot up onto the bench or step, standing fully upright."}, {"sv": "Kliv ner med vänster fot följt av höger fot och återgå till startpositionen.", "en": "Step back down with your left foot, followed by your right foot, returning to the starting position."}, {"sv": "Upprepa önskat antal repetitioner och byt sedan ben.", "en": "Repeat for the desired number of repetitions, then switch legs."}]$instr$::jsonb WHERE name = 'Step-up med hantlar' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Stå framför en step eller plattform med en hantel i varje hand och handflatorna vända mot sidorna.", "en": "Stand in front of a step or platform with a dumbbell in each hand, palms facing your sides."}, {"sv": "Placera höger fot på steppen och se till att hela foten är på ytan.", "en": "Place your right foot on the step, ensuring your entire foot is on the surface."}, {"sv": "Tryck genom höger häl, lyft dig upp på steppen och ta med vänster fot upp.", "en": "Push through your right heel and lift your body up onto the step, bringing your left foot up as well."}, {"sv": "När båda fötterna är på steppen sänker du vänster fot tillbaka till startpositionen medan höger fot stannar kvar på steppen.", "en": "Once both feet are on the step, lower your left foot back down to the starting position, keeping your right foot on the step."}, {"sv": "Upprepa rörelsen och växla vilken fot du kliver upp med varje gång.", "en": "Repeat the movement, alternating which foot you step up with each time."}, {"sv": "Fortsätt i önskat antal repetitioner.", "en": "Continue for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Step-up med utfall och hantlar' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Stå framför en bänk eller step med en hantel i varje hand och handflatorna vända mot kroppen.", "en": "Stand in front of a bench or step with a dumbbell in each hand, palms facing your body."}, {"sv": "Placera höger fot på bänken eller steppen och se till att hela foten har kontakt med ytan.", "en": "Place your right foot on the bench or step, ensuring your entire foot is in contact with the surface."}, {"sv": "Kliv upp på bänken eller steppen med höger fot och tryck genom hälen för att lyfta kroppen.", "en": "Step up onto the bench or step with your right foot, pushing through your heel to lift your body up."}, {"sv": "Samtidigt som du kliver upp lyfter du vänster knä mot bröstet.", "en": "As you step up, simultaneously lift your left knee towards your chest."}, {"sv": "Pausa i toppen av rörelsen och sänk sedan långsamt vänster fot till golvet medan höger fot stannar kvar på bänken eller steppen.", "en": "Pause at the top of the movement, then slowly lower your left foot back to the ground while keeping your right foot on the bench or step."}, {"sv": "Upprepa rörelsen med vänster fot på bänken eller steppen.", "en": "Repeat the movement with your left foot on the bench or step."}, {"sv": "Fortsätt växla mellan höger och vänster fot i önskat antal repetitioner.", "en": "Continue alternating between your right and left foot for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Step-up split squat med hantlar' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Stå upprätt på ett stabilt steg som är 15 till 30 cm högt, med tårna framåt och händerna på höfterna eller utsträckta för balans.", "en": "Stand tall on a sturdy step 15–30 cm high; toes forward, hands on hips or out for balance."}, {"sv": "Flytta vikten helt över det arbetande benet, håll bäckenet i våg och bålen spänd.", "en": "Shift your weight fully over the working leg, keeping pelvis level and core braced."}, {"sv": "Böj ståbenets knä och höft för att sänka dig, och låt den fria hälen sträva mot golvet framför.", "en": "Bend the stance knee and hip to descend, letting the free heel reach toward the floor in front."}, {"sv": "Låt ståbenets knä följa linjen över andra till tredje tån, låt det inte falla inåt.", "en": "Track the stance knee over the second–third toe; do not let it cave inward."}, {"sv": "Nudda golvet lätt med den fria hälen utan att lägga över vikt på den.", "en": "Lightly tap the floor with the free heel without transferring weight to it."}, {"sv": "Tryck genom ståbenets mellanfot och häl för att sträcka knä och höft och återgå till startpositionen.", "en": "Press through the stance midfoot/heel to extend the knee and hip and return to the start."}, {"sv": "Genomför alla reps långsamt och kontrollerat, byt sedan ben.", "en": "Complete all reps under slow control, then switch legs."}]$instr$::jsonb WHERE name = 'Stepdown knäböj' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Stå med fötterna axelbrett isär och håll en hantel i varje hand med överhandsgrepp.", "en": "Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip."}, {"sv": "Håll ryggen rak och bålen spänd, fäll i höften och sänk hantlarna mot golvet med en lätt böj i knäna.", "en": "Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing a slight bend in your knees."}, {"sv": "Sänk hantlarna tills du känner en sträckning i baksida lår, kläm sedan åt sätesmusklerna och tryck genom hälarna för att återgå till startpositionen.", "en": "Lower the dumbbells until you feel a stretch in your hamstrings, then squeeze your glutes and push through your heels to return to the starting position."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Stiff leg marklyft med hantlar' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Justera höjden på smithmaskinens stång till en bekväm position.", "en": "Adjust the height of the smith machine bar to a comfortable position."}, {"sv": "Stå med fötterna axelbrett isär och tårna något utåtvridna.", "en": "Stand with your feet shoulder-width apart, toes slightly turned out."}, {"sv": "Placera skivstången över övre delen av ryggen, vilande på kappmusklerna.", "en": "Place the barbell across your upper back, resting it on your traps."}, {"sv": "Spänn bålen och håll bröstet uppe medan du långsamt sänker kroppen genom att böja knän och höfter.", "en": "Engage your core and keep your chest up as you slowly lower your body by bending your knees and hips."}, {"sv": "Fortsätt sänka dig tills låren är parallella med golvet, eller så lågt du bekvämt kan komma.", "en": "Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go."}, {"sv": "Pausa ett ögonblick, tryck sedan genom hälarna för att återgå till startpositionen.", "en": "Pause for a moment, then push through your heels to return to the starting position."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Stolsknäböj i smithmaskin' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Börja hängande i ett par ringar med helt sträckta armar och kroppen i en rak linje.", "en": "Start by hanging from a pair of rings with your arms fully extended and your body in a straight line."}, {"sv": "Sära brett på benen så att du bildar en straddleposition.", "en": "Spread your legs wide apart, forming a straddle position."}, {"sv": "Spänn bålen och sänk långsamt kroppen tills armarna är parallella med golvet.", "en": "Engage your core and slowly lower your body until your arms are parallel to the ground."}, {"sv": "Håll positionen några sekunder och pressa dig sedan tillbaka upp till startpositionen.", "en": "Hold this position for a few seconds, then push yourself back up to the starting position."}, {"sv": "Upprepa i önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Straddle maltese' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Börja i en armhävningsposition med händerna axelbrett isär och benen brett särade.", "en": "Start in a push-up position with your hands shoulder-width apart and your feet spread wide apart."}, {"sv": "Spänn bålen och flytta långsamt vikten framåt så att axlarna kommer över händerna.", "en": "Engage your core and slowly shift your weight forward, bringing your shoulders over your hands."}, {"sv": "Böj armbågarna och sänk kroppen mot golvet, håll armbågarna nära sidorna.", "en": "Bend your elbows and lower your body towards the ground, keeping your elbows close to your sides."}, {"sv": "Pausa ett ögonblick i botten, tryck sedan genom händerna för att sträcka armarna och lyfta kroppen tillbaka till startpositionen.", "en": "Pause for a moment at the bottom, then push through your hands to straighten your arms and lift your body back up to the starting position."}, {"sv": "Upprepa i önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Straddle planche' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Stå upprätt med fötterna axelbrett isär.", "en": "Stand tall with your feet shoulder-width apart."}, {"sv": "Sträck armarna rakt fram i axelhöjd.", "en": "Extend your arms straight out in front of you at shoulder height."}, {"sv": "Korsa armarna framför kroppen, med höger arm ovanpå vänster arm.", "en": "Cross your arms in front of your body, with your right arm on top of your left arm."}, {"sv": "Fläta ihop fingrarna och pressa handflatorna mot varandra.", "en": "Interlace your fingers and press your palms together."}, {"sv": "Kläm försiktigt ihop skulderbladen och pressa händerna framåt tills du känner en stretch i bröstet och axlarnas framsida.", "en": "Gently squeeze your shoulder blades together and push your hands forward, feeling a stretch in your chest and front of your shoulders."}, {"sv": "Håll stretchen i 20 till 30 sekunder och släpp sedan.", "en": "Hold the stretch for 20-30 seconds, then release."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Stretch för bröst och främre axel' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Sitt på kanten av en stol med rak rygg och fötterna plant i golvet.", "en": "Sit on the edge of a chair with your back straight and feet flat on the ground."}, {"sv": "Sträck ut ena benet rakt framför dig med hälen i golvet.", "en": "Extend one leg straight out in front of you, keeping your heel on the ground."}, {"sv": "Luta dig lätt framåt tills du känner en stretch i lårets framsida.", "en": "Lean forward slightly, feeling a stretch in your quadriceps."}, {"sv": "Håll positionen i 20 till 30 sekunder.", "en": "Hold this position for 20-30 seconds."}, {"sv": "Byt ben och upprepa stretchen.", "en": "Switch legs and repeat the stretch."}]$instr$::jsonb WHERE name = 'Stretch med utsträckt ben på stol' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Stå med fötterna axelbrett isär.", "en": "Stand with your feet shoulder-width apart."}, {"sv": "Ta ett steg framåt med höger fot och håll ryggen rak.", "en": "Take a step forward with your right foot, keeping your back straight."}, {"sv": "Sänk kroppen genom att böja knäna tills höger lår är parallellt med golvet.", "en": "Lower your body by bending your knees until your right thigh is parallel to the ground."}, {"sv": "Tryck genom höger häl för att återgå till startpositionen.", "en": "Push through your right heel to return to the starting position."}, {"sv": "Upprepa med vänster ben.", "en": "Repeat with your left leg."}, {"sv": "Fortsätt växla ben önskat antal repetitioner.", "en": "Continue alternating legs for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Stretchutfall med vikt' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Se till att landningsytan framför dig är fri och stå med fötterna axelbrett isär med fatet strax framför dig, greppa kanterna eller sidorna stadigt.", "en": "Clear a safe landing zone in front of you and stand shoulder‑width apart with the keg slightly in front, gripping the rims/sides securely."}, {"sv": "Fäll i höften med rak rygg, mjuka upp knäna och spänn magen medan du drar fatet så att det svingar lätt mellan benen.", "en": "Hinge at the hips with a flat back, soften the knees, and brace your abs as you pull the keg to swing slightly between your legs."}, {"sv": "Tryck ifrån golvet och sträck höfter, knän och vrister explosivt, spänn sätet medan fatet rör sig uppåt.", "en": "Drive through the floor and extend hips, knees, and ankles explosively, squeezing the glutes as the keg travels upward."}, {"sv": "Håll bröstet högt, gör en axelryckning och styr fatet över huvudet med armar som sträcks, släpp när fatet är i en stigande båge strax över ögonhöjd.", "en": "Keep the chest tall, shrug, and guide the keg overhead with straightening arms; release when the keg is on a rising arc slightly above eye level."}, {"sv": "Avsluta i upprätt läge med höfter och knän helt sträckta och håll kroppen borta från fatets bana.", "en": "Finish tall with hips and knees locked out, keeping your body out of the keg’s path."}, {"sv": "Låt fatet landa på den fria ytan, gå sedan fram till det och återta din position och ditt grepp inför nästa repetition.", "en": "Let the keg land in the clear area, then walk to it and reset your stance and grip for the next repetition."}]$instr$::jsonb WHERE name = 'Strongman fatkast' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Stå med fötterna axelbrett vid den fria änden av den ledade stången, med smalbenen nära redskapet.", "en": "Stand with feet shoulder-width at the free end of the hinged pole, shins close to the implement."}, {"sv": "Greppa änden stadigt med båda händerna underifrån, med bröstet uppe, axlarna stabila och ryggen neutral.", "en": "Grip the end securely with both hands underneath, chest up, shoulders packed, and spine neutral."}, {"sv": "Spänn bålen, dra stången tätt mot kroppen och inled lyftet genom att trycka genom hälarna och sträcka knän och höfter samtidigt.", "en": "Brace your core, pull the pole tight to your body, and initiate the lift by driving through your heels, extending knees and hips together."}, {"sv": "Håll redskapet nära när det passerar knäna, justera greppet vid behov för att gå över från att lyfta till att trycka.", "en": "Keep the implement close as it rises past the knees; re-adjust your hand position if needed to transition from lifting to pushing."}, {"sv": "Fortsätt sträcka höfter och knän medan du driver stången uppåt, när den närmar sig lodrätt läge kliver du fram under den och pressar med armarna för att styra den över.", "en": "Continue hip and knee extension while driving the pole upward; as it nears vertical, step forward under it and press through the arms to guide it over."}, {"sv": "Avsluta med att kontrollerat tippa stången förbi balanspunkten och låt den falla säkert åt andra sidan.", "en": "Finish by tipping the pole past its balance point under control, letting it fall safely to the opposite side."}, {"sv": "Återta din position på den nya sidan, spänn bålen igen och upprepa. Undvik att rycka, vrida dig eller runda ryggen i något skede.", "en": "Reset your stance on the new side, re-brace, and repeat. Avoid jerking, twisting, or rounding your back at any point."}]$instr$::jsonb WHERE name = 'Strongman fingals fingers' AND user_id IS NULL;
