UPDATE exercises SET instructions = $instr$[{"sv": "Stå med fötterna axelbrett isär och håll en hantel i varje hand i axelhöjd med handflatorna framåt.", "en": "Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing forward."}, {"sv": "Pressa den ena hanteln över huvudet tills armen är helt sträckt.", "en": "Press one dumbbell overhead, fully extending your arm."}, {"sv": "Sänk tillbaka hanteln till axelhöjd.", "en": "Lower the dumbbell back to shoulder level."}, {"sv": "Upprepa med den andra armen.", "en": "Repeat with the other arm."}, {"sv": "Fortsätt växla mellan armarna önskat antal repetitioner.", "en": "Continue alternating arms for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Stående växelvis axelpress med hantlar' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Stå rakt med en hantel i varje hand, handflatorna mot kroppen.", "en": "Stand up straight with a dumbbell in each hand, palms facing your body."}, {"sv": "Håll armbågarna nära överkroppen och ryggen rak.", "en": "Keep your elbows close to your torso and your back straight."}, {"sv": "Andas ut och curla hanteln i höger hand mot axeln medan du håller överarmen stilla.", "en": "Exhale and curl the dumbbell in your right hand towards your shoulder, keeping your upper arm stationary."}, {"sv": "Fortsätt lyfta hanteln tills biceps är helt kontraherad och hanteln är i axelhöjd.", "en": "Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level."}, {"sv": "Andas in och sänk långsamt tillbaka hanteln till startpositionen.", "en": "Inhale and slowly lower the dumbbell back to the starting position."}, {"sv": "Upprepa curlen med vänster hand.", "en": "Repeat the curl with your left hand."}, {"sv": "När du har gjort curlen med vänster hand andas du ut och pressar hanteln i höger hand över huvudet.", "en": "After completing the curl with your left hand, exhale and press the dumbbell in your right hand overhead."}, {"sv": "Sträck armen helt och håll kvar ett ögonblick i toppläget.", "en": "Extend your arm fully and hold for a moment at the top."}, {"sv": "Andas in och sänk långsamt tillbaka hanteln till startpositionen.", "en": "Inhale and slowly lower the dumbbell back to the starting position."}, {"sv": "Upprepa pressen med vänster hand.", "en": "Repeat the press with your left hand."}, {"sv": "Fortsätt växla mellan curl och press önskat antal repetitioner.", "en": "Continue alternating between curls and presses for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Stående växelvis hammercurl med press' AND user_id IS NULL;
