UPDATE exercises SET instructions = $instr$[{"sv": "Stå upprätt med en hantel i varje hand och handflatorna vända framåt.", "en": "Stand up straight with a dumbbell in each hand, palms facing forward."}, {"sv": "Placera överarmarna mot preacherbänken och håll armbågarna lätt böjda.", "en": "Place your upper arms against the preacher bench and keep your elbows slightly bent."}, {"sv": "Curla upp hantlarna mot axlarna och håll överarmarna stilla.", "en": "Curl the dumbbells up towards your shoulders while keeping your upper arms stationary."}, {"sv": "I toppen av rörelsen roterar du handlederna så att handflatorna vänds nedåt.", "en": "At the top of the movement, rotate your wrists so that your palms are facing downward."}, {"sv": "Sänk långsamt tillbaka hantlarna till startpositionen och rotera samtidigt tillbaka handlederna till utgångsläget.", "en": "Slowly lower the dumbbells back to the starting position, rotating your wrists back to the starting position as well."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Stående zottman preacher curl' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Stå med fötterna axelbrett isär och håll en skivstång i ena handen med överhandsgrepp.", "en": "Stand with your feet shoulder-width apart, holding a barbell in one hand with an overhand grip."}, {"sv": "Håll ryggen rak och bålen spänd.", "en": "Keep your back straight and your core engaged."}, {"sv": "Fäll i höfterna och sänk skivstången längs utsidan av benet, med rak arm och bröstet uppe.", "en": "Bend at the hips and lower the barbell towards the outside of your leg, keeping your arm straight and your chest up."}, {"sv": "Sänk skivstången så långt du kan med bibehållen god teknik.", "en": "Lower the barbell as far as you can while maintaining good form."}, {"sv": "Pausa ett ögonblick och återgå sedan långsamt till startpositionen.", "en": "Pause for a moment, then slowly return to the starting position."}, {"sv": "Upprepa önskat antal repetitioner och byt sedan sida.", "en": "Repeat for the desired number of repetitions, then switch sides."}]$instr$::jsonb WHERE name = 'Suitcase marklyft' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Stå med fötterna bredare än axelbrett och tårna pekande utåt.", "en": "Stand with your feet wider than shoulder-width apart, toes pointing outwards."}, {"sv": "Håll en kettlebell med båda händerna framför kroppen med armarna sträckta nedåt.", "en": "Hold a kettlebell with both hands in front of your body, arms extended downwards."}, {"sv": "Böj knäna och sänk höfterna till en knäböjsposition med rak rygg.", "en": "Bend your knees and lower your hips into a squat position, keeping your back straight."}, {"sv": "Tryck genom hälarna och sträck explosivt ut höfter och knän medan du drar kettlebellen upp mot hakan.", "en": "Drive through your heels and explosively extend your hips and knees, pulling the kettlebell up towards your chin."}, {"sv": "Håll armbågarna höga och breda när du drar upp kettlebellen och kläm ihop skulderbladen.", "en": "As you pull the kettlebell up, keep your elbows high and wide, and squeeze your shoulder blades together."}, {"sv": "Sänk kettlebellen tillbaka till startpositionen och upprepa önskat antal repetitioner.", "en": "Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Sumo high pull med kettlebell' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Ställ fötterna bredare än axelbrett med tårna utåtvridna 30 till 45 grader. Greppa hantelns ena ände med båda händerna, med raka armar hängande mellan benen.", "en": "Set feet wider than shoulder width with toes turned out 30–45°, grip one head of the dumbbell with both hands, arms straight and hanging between the legs."}, {"sv": "Spänn bålen, håll ryggen neutral och skjut höften bakåt medan du böjer knäna lätt. Låt hanteln röra sig mellan låren.", "en": "Brace the core, keep a neutral spine, and push the hips back while bending the knees slightly; let the dumbbell travel between the thighs."}, {"sv": "Håll smalbenen nästan vertikala, knäna i linje över tårna, axlarna stabila och tyngden över mellanfot och hälar.", "en": "Keep shins near vertical, knees tracking over toes, shoulders packed, and weight through mid‑foot to heels."}, {"sv": "Pausa i slutet av höftfällningen med överkroppen lutad framåt, utan att runda ryggen.", "en": "At the end of the hinge, pause with the torso angled forward without rounding the back."}, {"sv": "Tryck fötterna i golvet och skjut höften snabbt framåt, kläm åt sätesmusklerna och res dig upp. Låt armarna vara raka medan hanteln dras framåt av höftsträckningen.", "en": "Drive the feet into the floor and snap the hips forward, squeezing the glutes to stand tall; let the arms stay straight as the dumbbell is pulled forward by hip extension."}, {"sv": "Avsluta med höfter och knän helt utsträckta, revbenen nedåt och utan att översträcka ländryggen.", "en": "Finish with hips and knees fully extended, ribs down, and no low‑back hyperextension."}, {"sv": "Upprepa genom att fälla i höften igen och föra hanteln kontrollerat tillbaka mellan benen. Håll ett jämnt tempo och nacken neutral genom hela rörelsen.", "en": "Repeat by hinging again, guiding the dumbbell back between the legs under control; maintain a smooth tempo and neutral neck throughout."}]$instr$::jsonb WHERE name = 'Sumo pull through med hantel' AND user_id IS NULL;
UPDATE exercises SET instructions = $instr$[{"sv": "Ställ in smithmaskinen med stången i höfthöjd.", "en": "Set up the smith machine with the barbell at hip height."}, {"sv": "Stå med fötterna bredare än axelbrett och tårna pekande utåt.", "en": "Stand with your feet wider than shoulder-width apart, toes pointing outwards."}, {"sv": "Placera dig under stången så att den vilar på övre delen av ryggen och axlarna.", "en": "Position yourself under the barbell, resting it on your upper back and shoulders."}, {"sv": "Spänn bålen och håll bröstet lyft när du sänker kroppen ner i en knäböj genom att skjuta höfterna bakåt och böja knäna.", "en": "Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees."}, {"sv": "Sänk dig tills låren är parallella med golvet, eller så djupt som känns bekvämt.", "en": "Lower yourself until your thighs are parallel to the ground, or as low as you can comfortably go."}, {"sv": "Pausa ett ögonblick i botten och tryck sedan genom hälarna tillbaka till startpositionen.", "en": "Pause for a moment at the bottom, then push through your heels to return to the starting position."}, {"sv": "Upprepa önskat antal repetitioner.", "en": "Repeat for the desired number of repetitions."}]$instr$::jsonb WHERE name = 'Sumoknäböj i smithmaskin' AND user_id IS NULL;
