UPDATE exercises SET instructions = $instr$[{"sv": "Börja med att ligga på rygg med benen sträckta och kettlebellen i höger hand, armen helt sträckt rakt ovanför axeln.", "en": "Start by lying on your back with your legs extended and the kettlebell held in your right hand, arm fully extended above your shoulder."}, {"sv": "Böj höger knä och placera höger fot platt i golvet medan vänster ben förblir sträckt.", "en": "Bend your right knee and place your right foot flat on the ground, keeping your left leg extended."}, {"sv": "Tryck genom höger fot och lyft höfterna från golvet så att du kommer upp i en bryggposition.", "en": "Pressing through your right foot, lift your hips off the ground, coming into a bridge position."}, {"sv": "För vänster ben under kroppen, böj vänster knä och placera vänster fot platt i golvet.", "en": "Slide your left leg underneath your body, bending your left knee and placing your left foot flat on the ground."}, {"sv": "Rotera överkroppen åt vänster och sätt vänster hand i golvet som stöd.", "en": "Rotate your torso to the left, bringing your left hand to the ground for support."}, {"sv": "Tryck genom höger fot och vänster hand och lyft överkroppen från golvet så att du kommer upp i knästående.", "en": "Pressing through your right foot and left hand, lift your torso off the ground, coming into a kneeling position."}, {"sv": "Res dig upp från knästående med kettlebellen sträckt över huvudet.", "en": "From the kneeling position, stand up, keeping the kettlebell extended overhead."}, {"sv": "Vänd på rörelsen för att återgå till startpositionen.", "en": "Reverse the movement to return to the starting position."}, {"sv": "Upprepa övningen på andra sidan och börja med kettlebellen i vänster hand.", "en": "Repeat the exercise on the other side, starting with the kettlebell in your left hand."}]$instr$::jsonb WHERE name = 'Turkish get up med kettlebell squatvariant' AND user_id IS NULL;
