UPDATE exercises SET instructions = $instr$[{"sv": "Stå med fötterna höftbrett isär, stången över fotens mitt och händerna strax utanför benen. Spänn bålen och håll ryggen neutral.", "en": "Stand with feet hip-width, bar over midfoot, hands just outside legs; brace and set a neutral spine."}, {"sv": "Inled en power clean: tryck ifrån golvet, sträck höfter och knän explosivt, rulla upp axlarna, dra dig sedan under stången och fånga den på axlarna med höga armbågar.", "en": "Initiate a power clean: push through the floor, extend hips and knees violently, shrug, then pull under and catch the bar on the shoulders with elbows high."}, {"sv": "Ställ fötterna axelbrett och gör en kontrollerad frontböj till bekvämt djup, med upprätt överkropp och knäna i linje över tårna. Res dig upp.", "en": "Set feet shoulder-width and perform one controlled front squat to comfortable depth, keeping torso upright and knees tracking over toes; stand tall."}, {"sv": "Sjunk ner 5 till 8 cm genom att böja knän och höfter samtidigt, tryck sedan uppåt och pressa stången över huvudet till fullt utsträckta armar (push press), med revbenen nere.", "en": "Dip 2-3 inches by bending knees and hips together, then drive up and press the bar overhead to full lockout (push press) with ribs down."}, {"sv": "Sänk stången tillbaka till frontpositionen på axlarna, sedan till höfterna, och för den kontrollerat ner till golvet för att börja om.", "en": "Lower the bar back to the front rack, then to the hips, and guide it to the floor with control to reset."}, {"sv": "Upprepa sekvensen i föreskrivet antal reps. Avbryt om stånghastigheten sjunker eller tekniken försämras.", "en": "Repeat the sequence for the prescribed reps, stopping if bar speed slows or form degrades."}]$instr$::jsonb WHERE name = 'Tyngdlyftningskomplex med skivstång' AND user_id IS NULL;
